-- =============================================================================
-- 468 — LE CAHIER D'EXERCICES DE 6E (partie 2)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/6e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 468 --niveau 6e --fichiers francais.n1,histoire-geo.n1a,histoire-geo.n1b,histoire-geo.n2a --suffixe 2 > supabase/contenu/468_exercices_6e_2.sql
--
-- 81 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n1             27 exercices · 9 chapitres
--   histoire-geo.n1a        18 exercices · 6 chapitres
--   histoire-geo.n1b        18 exercices · 6 chapitres
--   histoire-geo.n2a        18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('8f69c9d1-7cdd-5e7e-b37d-ff57ba7a4e4b'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un récit de création, mot à mot","competence":"analyser-texte","situation":"Ton professeur te donne un court récit de création, adapté de la Genèse. Avant de le commenter, il faut repérer comment il est écrit.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Au commencement","auteur":"D’après le récit de la Genèse — texte adapté pour l’exercice","blocs":["Au commencement, la terre était informe et couverte d’eau. Tout était sombre.","Dieu parla : la lumière apparut. Il sépara la lumière de l’obscurité.","Le deuxième jour, il créa le ciel. Puis la terre sèche sortit des eaux.","Le septième jour, Dieu cessa son travail."]}],"questions":[{"enonce":"Les actions principales d’un récit se racontent au **passé simple**. Touche tous les verbes au passé simple.","aide":"Ce sont les verbes qui font avancer l’histoire : cherche ceux qui se terminent par -a, -ut ou -it.","type":"zone","document":"recit","multiple":true},{"enonce":"Dans ce récit, comment Dieu fait-il apparaître la lumière ?","aide":"Relis le deuxième paragraphe : quel verbe précède « la lumière apparut » ?","type":"choix","options":[{"id":"a","texte":"Il la tire d’un grand feu"},{"id":"b","texte":"Il parle, et la lumière apparaît"},{"id":"c","texte":"Il la reçoit d’un autre dieu"},{"id":"d","texte":"Il la fabrique avec ses mains"}],"multiple":false},{"enonce":"Le premier paragraphe est à l’imparfait (« était »). À quoi sert ce temps ici ?","aide":"Dans le premier paragraphe, personne n’agit encore : on regarde un paysage.","type":"choix","options":[{"id":"a","texte":"À annoncer la suite du récit demain"},{"id":"b","texte":"À décrire le décor avant l’action"},{"id":"c","texte":"À faire parler un personnage de l’histoire"},{"id":"d","texte":"À raconter les actions principales"}],"multiple":false},{"enonce":"Complète : ce récit est partagé, avec des variantes, par trois religions monothéistes.","aide":"Le cours cite trois religions qui ne reconnaissent qu’un seul dieu.","type":"trous","segments":["Le judaïsme, le christianisme et l’",0," partagent ce récit avec des variantes."],"banque":["bouddhisme","islam","shintoïsme","hindouisme"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m17","m19","m29","m36","m43"]},"explication":"Les six verbes **parla, apparut, sépara, créa, sortit, cessa** sont au passé simple : ils font avancer le récit. « était » (imparfait) ne fait que poser le décor."},{"cle":{"type":"choix","ids":["b"]},"explication":"Dieu **parle** et ce qu’il dit existe. C’est ce que le cours appelle la **parole créatrice** : dire suffit à faire exister."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’**imparfait** installe le décor et l’état des choses ; le **passé simple** fait avancer l’histoire. C’est la répartition à retenir pour tout récit."},{"cle":{"type":"trous","trous":[["islam"]]},"affichage":"islam","explication":"Les trois monothéismes sont le judaïsme, le christianisme et l’**islam**, qui ne reconnaissent qu’un seul dieu (*monos* = seul, *theos* = dieu)."}]$ex$::jsonb),
  ('8f69c9d1-7cdd-5e7e-b37d-ff57ba7a4e4b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les six jours et le jour de repos","competence":"lire-tableau","situation":"Un musée présente la création en sept jours d’après la Genèse. Les panneaux ont été mélangés : à toi de les remettre en ordre en lisant le tableau.","documents":[{"id":"jours","type":"tableau","titre":"Les jours de la création, d’après la Genèse (panneaux mélangés)","colonnes":["Ce qui apparaît","Jour"],"lignes":[["Les poissons et les oiseaux","5"],["La lumière","1"],["Le soleil, la lune et les étoiles","4"],["Le repos","7"],["Le ciel","2"],["Les animaux de la terre et les humains","6"],["La terre sèche et les plantes","3"]],"source":"Tableau écrit pour l’exercice, d’après le récit de la Genèse"}],"questions":[{"enonce":"Remets les créations dans l’ordre du récit, du premier jour au sixième.","aide":"Lis la colonne « Jour » : elle te donne le rang de chaque création.","type":"ordre","items":[{"id":"a","texte":"Les poissons et les oiseaux"},{"id":"b","texte":"Le soleil, la lune et les étoiles"},{"id":"c","texte":"La lumière"},{"id":"d","texte":"La terre sèche et les plantes"},{"id":"e","texte":"Le ciel"},{"id":"f","texte":"Les animaux de la terre et les humains"}]},{"enonce":"Touche la case qui donne le jour où apparaissent le soleil, la lune et les étoiles.","aide":"Trouve d’abord la ligne des astres, puis regarde sa colonne « Jour ».","type":"zone","document":"jours","multiple":false},{"enonce":"Combien de jours d’action précèdent le jour de repos ?","aide":"Le repos est au jour 7 : compte les jours qui le précèdent.","type":"nombre"},{"enonce":"Complète la phrase sur la progression de la création.","aide":"Pense au mouvement : on commence par les grands ensembles, on finit par les êtres précis.","type":"trous","segments":["La création va du plus ",0," (la lumière, le ciel) au plus ",1," (les animaux, l’humain)."],"banque":["lointain","particulier","ancien","général"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["c","e","d","b","a","f"]},"explication":"Du jour 1 au jour 6 : la lumière, le ciel, la terre et les plantes, les astres, les poissons et les oiseaux, puis les animaux de la terre et les humains."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le soleil, la lune et les étoiles apparaissent au **quatrième jour**."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"La création est racontée en sept jours : **six** jours d’action, puis un jour de repos."},{"cle":{"type":"trous","trous":[["general"],["particulier"]]},"affichage":"général · particulier","explication":"Le récit va du plus **général** au plus **particulier** : c’est la progression qui donne son ordre au texte."}]$ex$::jsonb),
  ('8f69c9d1-7cdd-5e7e-b37d-ff57ba7a4e4b'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Noé : le monde qui recommence","competence":"analyser-texte","situation":"Dans un manuel, deux documents se font face : un récit de déluge adapté de la Genèse, et un petit tableau qui le compare à la création. À toi de montrer comment ce texte est construit.","documents":[{"id":"deluge","type":"texte","genre":"recit","titre":"Noé et l’arche","auteur":"D’après le récit de la Genèse — texte adapté pour l’exercice","blocs":["Selon la Genèse, les hommes se conduisaient mal et Dieu décida d’effacer le monde. Seul Noé, un homme juste, fut épargné.","Noé construisit une arche et y fit entrer sa famille et un couple de chaque animal. Alors la pluie tomba pendant quarante jours. Ensuite, les eaux montèrent et couvrirent la terre.","Enfin, elles baissèrent et l’arche se posa sur une montagne. Puis Noé sortit avec tous les vivants : le monde pouvait recommencer."]},{"id":"compare","type":"tableau","titre":"Créer et recréer","colonnes":["Récit","Au début","À la fin"],"lignes":[["La création","Une terre informe, couverte d’eau","Un monde ordonné, en six jours"],["Le déluge","Un monde habité par les hommes","Un monde recommencé avec Noé"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Les **connecteurs de temps** organisent le récit. Touche les quatre connecteurs de temps du texte.","aide":"Ce sont de petits mots qui annoncent la suite : « au commencement », « puis »…","type":"zone","document":"deluge","multiple":true},{"enonce":"Range ces verbes du texte selon leur temps.","aide":"Le passé simple raconte une action achevée ; l’imparfait décrit une situation qui dure.","type":"categories","categories":[{"id":"c0","texte":"Passé simple"},{"id":"c1","texte":"Imparfait"}],"items":[{"id":"i0","texte":"tomba"},{"id":"i1","texte":"pouvait"},{"id":"i2","texte":"décida"},{"id":"i3","texte":"construisit"},{"id":"i4","texte":"se conduisaient"},{"id":"i5","texte":"se posa"}]},{"enonce":"Pourquoi dit-on que le déluge est un récit de **re**-création ?","aide":"Regarde la ligne « Le déluge » du tableau : que devient le monde, du début à la fin ?","type":"choix","options":[{"id":"a","texte":"Le monde est effacé puis recommencé avec Noé"},{"id":"b","texte":"Noé invente un nouveau langage"},{"id":"c","texte":"Dieu crée un deuxième monde en secret"},{"id":"d","texte":"Le monde est créé en six jours"}],"multiple":false},{"enonce":"Touche la case du tableau qui dit comment le monde recommence après le déluge.","aide":"Cherche la ligne « Le déluge », puis la colonne « À la fin ».","type":"zone","document":"compare","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m38","m45","m53","m64"]},"explication":"**Alors, Ensuite, Enfin, Puis** : ces connecteurs de temps font avancer le récit étape par étape."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**décida, construisit, tomba, se posa** font avancer l’histoire (passé simple). **se conduisaient** et **pouvait** décrivent un état des choses (imparfait)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le déluge **efface** le monde, puis le **recommence** avec Noé : c’est une création de plus, d’où le préfixe *re*-."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Après le déluge, c’est « un monde **recommencé avec Noé** »."}]$ex$::jsonb),
  ('1f0ed8c8-b29a-5bd3-89ab-46dee89079f5'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui était là avant Zeus ?","competence":"analyser-document","situation":"Pour un exposé sur la mythologie grecque, tu as noté d’un seul trait comment Zeus est devenu le maître de l’Olympe. Mais tu as tout écrit à l’envers.","documents":[{"id":"resume","type":"texte","genre":"recit","titre":"Mes notes sur La Théogonie","auteur":"Résumé écrit pour l’exercice, d’après Hésiode","blocs":["Aujourd’hui, Zeus règne sur l’Olympe avec les douze dieux. Il y est arrivé en renversant Cronos. Cronos avait lui-même renversé son père, Ouranos, le Ciel, époux de Gaïa, la Terre. Tous deux étaient nés du Chaos."]},{"id":"domaines","type":"tableau","titre":"Fiche du musée : cinq dieux et leur domaine","colonnes":["Dieu","Domaine"],"lignes":[["Zeus","Le ciel"],["Poséidon","La mer"],["Hadès","Les Enfers"],["Athéna","La sagesse"],["Arès","La guerre"]],"enteteLignes":true,"source":"Fiche écrite pour l’exercice"}],"questions":[{"enonce":"Remets dans l’ordre les étapes de la naissance du monde, de la plus ancienne à la plus récente.","aide":"Le texte remonte le temps : commence par la dernière phrase et reviens en arrière.","type":"ordre","items":[{"id":"a","texte":"Cronos renverse son père"},{"id":"b","texte":"Le Chaos"},{"id":"c","texte":"Gaïa et Ouranos naissent"},{"id":"d","texte":"Zeus renverse Cronos"}]},{"enonce":"Touche la case qui dit quel est le domaine d’Hadès.","aide":"Trouve la ligne d’Hadès, puis lis la colonne « Domaine ».","type":"zone","document":"domaines","multiple":false},{"enonce":"Retrouve le sens du mot « polythéiste ».","aide":"Un polythéiste reconnaît plusieurs dieux : *poly* annonce la quantité.","type":"trous","segments":["*Poly* veut dire « ",0," » et *theos* veut dire « ",1," » : un polythéiste reconnaît plusieurs dieux."],"banque":["nombreux","monde","dieu","seul"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["b","c","a","d"]},"explication":"Le Chaos → Gaïa (la Terre) et Ouranos (le Ciel) → Cronos renverse son père → **Zeus** renverse Cronos et s’installe sur l’Olympe."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Hadès règne sur **les Enfers**."},{"cle":{"type":"trous","trous":[["nombreux","nombreuse","plusieurs"],["dieu"]]},"affichage":"nombreux · dieu","explication":"*Poly* = **nombreux**, *theos* = **dieu** : un polythéiste reconnaît plusieurs dieux, à l’inverse du monothéiste."}]$ex$::jsonb),
  ('1f0ed8c8-b29a-5bd3-89ab-46dee89079f5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une parole ou une famille ?","competence":"analyser-document","situation":"Deux élèves ont résumé le début d’un récit d’origine. L’un parle d’un dieu unique, l’autre de nombreux dieux. À toi de les classer, puis de t’en servir.","documents":[{"id":"debuts","type":"texte","genre":"recit","titre":"Deux débuts de récit","auteur":"Textes écrits pour l’exercice (résumés d’après Hésiode et la Genèse)","blocs":["**Récit A.** Au début, il n’y a que le Chaos. De lui naissent la Terre et le Ciel. Ils ont des enfants, et ces enfants se disputent le pouvoir.","**Récit B.** Au début, il n’y a que l’obscurité. Un dieu unique parle, et ce qu’il dit existe."]},{"id":"domaines","type":"tableau","titre":"Les domaines des dieux grecs","colonnes":["Dieu","Domaine"],"lignes":[["Zeus","Le ciel"],["Poséidon","La mer"],["Hadès","Les Enfers"],["Athéna","La sagesse"],["Arès","La guerre"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Lequel de ces deux débuts de récit est **polythéiste** ?","aide":"Compte les dieux : le récit raconte-t-il une famille de dieux ou un dieu unique qui parle ?","type":"choix","options":[{"id":"a","texte":"Les deux"},{"id":"b","texte":"Le récit A"},{"id":"c","texte":"Aucun des deux"},{"id":"d","texte":"Le récit B"}],"multiple":false},{"enonce":"Range chaque trait selon le type de récit.","aide":"Reviens aux deux récits : A raconte des générations, B une parole.","type":"categories","categories":[{"id":"c0","texte":"Chez les polythéistes"},{"id":"c1","texte":"Chez les monothéistes"}],"items":[{"id":"i0","texte":"Chaque dieu a son domaine"},{"id":"i1","texte":"Le monde naît d’une succession de générations"},{"id":"i2","texte":"Le monde naît d’une parole"},{"id":"i3","texte":"Un dieu unique, sans image"},{"id":"i4","texte":"Les dieux ont un corps et des défauts humains"}]},{"enonce":"Dans la Grèce ancienne, à quel dieu s’adresserait chacune de ces personnes ?","aide":"Utilise le tableau : chaque dieu a son domaine.","type":"association","gauche":[{"id":"g0","texte":"Un marin avant une traversée"},{"id":"g1","texte":"Un soldat avant la bataille"},{"id":"g2","texte":"Une élève qui cherche la sagesse"},{"id":"g3","texte":"Quelqu’un qui pense aux morts"}],"droite":[{"id":"d0","texte":"Hadès"},{"id":"d1","texte":"Poséidon"},{"id":"d2","texte":"Athéna"},{"id":"d3","texte":"Arès"}]},{"enonce":"Complète la phrase.","aide":"Le mot est dans le cours : il parle de la forme humaine des dieux.","type":"trous","segments":["Les dieux grecs ont un corps, un caractère et des défauts humains : ils sont ",0,"."],"banque":["monothéistes","invisibles","anthropomorphes","immortels"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Le **récit A** est polythéiste : le monde naît d’une succession de générations. Dans le récit B, un dieu unique crée par la parole."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0"}},"explication":"Chez les Grecs : générations, dieux à forme humaine, un domaine par dieu. Chez les monothéistes : **une parole** et **un dieu unique** sans image."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"Poséidon règne sur la **mer**, Arès sur la **guerre**, Athéna sur la **sagesse**, Hadès sur les **Enfers** : chaque dieu a son domaine."},{"cle":{"type":"trous","trous":[["anthropomorphes","anthropomorphe"]]},"affichage":"anthropomorphes","explication":"Les dieux grecs sont **anthropomorphes** : ils ont une forme et un caractère humains."}]$ex$::jsonb),
  ('1f0ed8c8-b29a-5bd3-89ab-46dee89079f5'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les dieux grecs dans notre langue","competence":"analyser-document","situation":"Dans le journal de la fête de la ville, un article cache quatre mots venus de la mythologie. Un petit tableau montre aussi que le déluge existe dans plusieurs cultures.","documents":[{"id":"article","type":"texte","genre":"article","titre":"La fête de la ville sous l’orage","auteur":"Article imaginé pour l’exercice","blocs":["Samedi, une panique a saisi la foule quand l’orage a éclaté.","Les organisateurs ont fourni un effort titanesque pour tout ranger avant la nuit.","Les visiteurs se perdaient dans un dédale d’allées et de stands.","Un candidat narcissique se prenait en photo devant chaque miroir."]},{"id":"deluge","type":"tableau","titre":"Le déluge dans trois récits","colonnes":["Culture","Récit","Héros du déluge"],"lignes":[["La Bible","La Genèse","Noé"],["La Grèce","Les récits grecs","?"],["La Mésopotamie","L’Épopée de Gilgamesh","Un homme sauvé des eaux"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Quatre mots de l’article viennent de noms de dieux, de héros ou de géants grecs. Touche-les tous.","aide":"Pense à la fin du cours : « panique », « narcissique », « titanesque »… et un quatrième.","type":"zone","document":"article","multiple":true},{"enonce":"Relie chaque mot à son origine.","aide":"Le nom de chaque mot ressemble déjà à celui de son origine.","type":"association","gauche":[{"id":"g0","texte":"panique"},{"id":"g1","texte":"narcissique"},{"id":"g2","texte":"titanesque"},{"id":"g3","texte":"dédale"}],"droite":[{"id":"d0","texte":"Dédale, l’architecte du labyrinthe"},{"id":"d1","texte":"Les Titans"},{"id":"d2","texte":"Narcisse"},{"id":"d3","texte":"Le dieu Pan"}]},{"enonce":"Dans le tableau, quel est le nom du héros du déluge grec ? (Un seul mot.)","aide":"Le cours cite ce nom entre parenthèses, à propos du déluge chez les Grecs.","type":"texte"},{"enonce":"D’après le tableau et le cours, quelle œuvre est bien plus ancienne que la Bible ?","aide":"Une seule des quatre œuvres vient de Mésopotamie, et le cours dit qu’elle est « bien plus ancienne que la Bible ».","type":"choix","options":[{"id":"a","texte":"Les récits grecs de Pandore"},{"id":"b","texte":"La Théogonie"},{"id":"c","texte":"L’Épopée de Gilgamesh"},{"id":"d","texte":"La Genèse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m18","m31","m39"]},"explication":"**panique, titanesque, dédale, narcissique** viennent de la mythologie grecque : le dieu Pan, les Titans, Dédale et Narcisse."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"Ces mots d’aujourd’hui gardent la trace des récits grecs : Pan, Narcisse, les Titans et Dédale."},{"cle":{"type":"texte","acceptes":["deucalion"]},"affichage":"Deucalion","explication":"Chez les Grecs, le héros du déluge est **Deucalion**."},{"cle":{"type":"choix","ids":["c"]},"explication":"*L’Épopée de Gilgamesh*, qui contient un déluge, est **bien plus ancienne que la Bible**. Comparer ces récits est plus passionnant que de les classer."}]$ex$::jsonb),
  ('26e5fcc3-931a-5cc7-8118-27f00ecde058'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Pourquoi le hérisson a des piquants","competence":"analyser-texte","situation":"Dans un recueil de contes « comme ça », tu lis une histoire qui explique pourquoi le hérisson a des piquants. Retrouve la façon dont elle est construite.","documents":[{"id":"conte","type":"texte","genre":"recit","titre":"Le hérisson et les noisettes","auteur":"Conte écrit pour l’exercice, à la manière des contes du « pourquoi »","blocs":["Ô lecteur curieux, écoute bien cette histoire.","Autrefois, quand le monde était tout neuf, le hérisson avait un pelage doux et lisse. Il était très gourmand.","Un soir, il vola toutes les noisettes de l’écureuil. Le vieux chêne se mit en colère et lui jeta un sort.","Aussitôt, tous les poils du hérisson se dressèrent et se changèrent en piquants.","Et depuis ce jour, tous les hérissons ont des piquants."]}],"questions":[{"enonce":"Le conteur s’adresse directement à celui qui lit. Touche le mot par lequel il l’appelle.","aide":"Regarde le tout début du texte, après le « Ô ».","type":"zone","document":"conte","multiple":false},{"enonce":"Remets dans l’ordre les trois étapes du conte.","aide":"Un conte étiologique commence par une situation où la chose n’existe pas encore.","type":"ordre","items":[{"id":"a","texte":"Tous les hérissons ont des piquants."},{"id":"b","texte":"Le hérisson a un pelage doux."},{"id":"c","texte":"Il vole les noisettes et le chêne le punit."}]},{"enonce":"Complète la phrase.","aide":"Le mot vient du grec *aitia*, « la cause ».","type":"trous","segments":["Ce conte est un conte ",0," : il explique pourquoi une chose est comme elle est."],"banque":["fantastique","scientifique","policier","étiologique"]},{"enonce":"Ce conte donne-t-il une vraie explication scientifique des piquants du hérisson ?","aide":"Un chêne qui jette un sort : est-ce de la science ?","type":"choix","options":[{"id":"a","texte":"Oui, il explique comment poussent les piquants"},{"id":"b","texte":"Non, il ne parle pas des piquants"},{"id":"c","texte":"Non, il fait seulement semblant d’expliquer"},{"id":"d","texte":"Oui, grâce au sort du chêne"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"**Lecteur** : le conteur lui parle directement. Ce procédé s’appelle l’**apostrophe**."},{"cle":{"type":"ordre","ids":["b","c","a"]},"explication":"Situation initiale (pelage doux) → événement (la faute et la punition) → situation finale (des piquants pour tous)."},{"cle":{"type":"trous","trous":[["etiologique"]]},"affichage":"étiologique","explication":"C’est un conte **étiologique** (du grec *aitia*, la cause)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un conte étiologique **fait semblant** d’expliquer. C’est le jeu qui plaît, ce n’est pas de la science."}]$ex$::jsonb),
  ('26e5fcc3-931a-5cc7-8118-27f00ecde058'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi la mer est salée","competence":"analyser-texte","situation":"Les élèves de ta classe comparent deux manières de lire un conte du « pourquoi ». Voici le texte sur lequel ils travaillent : retrouve où se cachent les trois étapes.","documents":[{"id":"moulin","type":"texte","genre":"recit","titre":"Le moulin du marin","auteur":"Conte écrit pour l’exercice, à la manière des contes du « pourquoi »","blocs":["Il y a très longtemps, la mer était douce comme l’eau d’une fontaine. Personne ne connaissait le sel.","Un marin gourmand reçut du roi des vagues un petit moulin magique, qui fabriquait du sel sur commande.","Le marin, toujours plus avide, emporta le moulin sur son bateau pour en vendre dans tous les ports. Mais il avait oublié la formule pour l’arrêter.","Le moulin tourna, tourna, tourna… Le sel s’entassa jusqu’à faire couler le bateau.","Et depuis ce jour, le moulin tourne encore au fond de l’eau, et la mer est salée."]}],"questions":[{"enonce":"Relie chaque étape du conte au passage qui la raconte.","aide":"La situation finale explique l’état actuel du monde : cherche le dernier paragraphe.","type":"association","gauche":[{"id":"g0","texte":"Situation initiale"},{"id":"g1","texte":"Événement"},{"id":"g2","texte":"Situation finale"}],"droite":[{"id":"d0","texte":"Le marin ne peut plus arrêter le moulin"},{"id":"d1","texte":"La mer est salée pour toujours"},{"id":"d2","texte":"La mer est douce, le sel n’existe pas"}]},{"enonce":"Le conteur répète trois fois le même mot pour faire entendre le moulin qui tourne. Touche-le chaque fois.","aide":"C’est un verbe au passé simple, répété à la suite dans le quatrième paragraphe.","type":"zone","document":"moulin","multiple":true},{"enonce":"Quelle faute du marin déclenche la punition ?","aide":"Relis le troisième paragraphe : que veut le marin, « toujours plus » ?","type":"choix","options":[{"id":"a","texte":"Il ment à tout le monde"},{"id":"b","texte":"Il refuse de travailler"},{"id":"c","texte":"Il est toujours plus avide"},{"id":"d","texte":"Il vole le roi des vagues"}],"multiple":false},{"enonce":"Le conte dit : « et la mer est salée ». Cette situation finale vaut…","aide":"La situation finale explique un état du monde d’aujourd’hui.","type":"choix","options":[{"id":"a","texte":"Pour toute la mer, depuis ce jour"},{"id":"b","texte":"Pour cette mer-ci seulement"},{"id":"c","texte":"Pour une seule saison"},{"id":"d","texte":"Pour le marin seulement"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Au début, le sel n’existe pas. L’**événement** est la faute (l’avidité) et ses suites. À la fin, la mer est salée **pour toujours**."},{"cle":{"type":"zone","ids":["m67","m68","m69"]},"explication":"Le verbe **tourna**, répété trois fois, imite le mouvement du moulin et fait entendre une voix de conteur."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est son **avidité** : il veut vendre du sel dans tous les ports et oublie la formule qui arrête le moulin."},{"cle":{"type":"choix","ids":["a"]},"explication":"La situation finale vaut **pour toujours** et pour **toute l’espèce** (ici, toute la mer), pas pour un seul cas."}]$ex$::jsonb),
  ('26e5fcc3-931a-5cc7-8118-27f00ecde058'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La tortue et sa maison : lire la voix du conteur","competence":"manier-langue","situation":"Tu prépares ton propre conte du « pourquoi ». Pour t’inspirer, tu étudies la voix du conteur dans un texte, puis tu ranges tes cartes d’écriture.","documents":[{"id":"tortue","type":"texte","genre":"recit","titre":"La tortue et sa maison","auteur":"Conte écrit pour l’exercice, à la manière des contes du « pourquoi »","blocs":["Écoute, ami, car cette histoire est vraie, enfin presque.","Au temps où les bêtes parlaient, la tortue n’avait pas de carapace. Elle était toute rose, toute molle, et très, très, très lente.","Un jour, le lion rugit : « Qui me portera jusqu’à la rivière ? » La tortue répondit : « Pfff ! Plus tard ! » Le lion rugit une deuxième fois, et la tortue répondit : « Pfff ! Plus tard ! »","Alors le roi des bêtes, très fâché, posa sur son dos une grosse pierre plate : « Puisque tu aimes tant rester sans bouger, tu porteras ta maison partout ! »","Et depuis ce jour, ô ami, toutes les tortues du monde portent leur maison sur le dos, et elles avancent lentement parce que c’est lourd."]},{"id":"cartes","type":"tableau","titre":"Mes cartes d’écriture (en vrac)","colonnes":["Carte"],"lignes":[["Écrire au passé simple et à l’imparfait"],["Inventer la faute"],["Finir par « et depuis ce jour… »"],["Choisir une particularité animale"],["Inventer la sanction"]],"source":"Fiche écrite pour l’exercice"}],"questions":[{"enonce":"Le conteur appelle deux fois son lecteur « ami ». Touche les deux fois où il s’adresse directement à lui.","aide":"Une fois au début, une fois dans la dernière phrase.","type":"zone","document":"tortue","multiple":true},{"enonce":"Range chaque passage selon le procédé du conteur.","aide":"L’apostrophe parle au lecteur ; la répétition redit ; l’humour glisse un sourire.","type":"categories","categories":[{"id":"c0","texte":"Apostrophe"},{"id":"c1","texte":"Répétition"},{"id":"c2","texte":"Humour"}],"items":[{"id":"i0","texte":"« Pfff ! Plus tard ! » dit deux fois"},{"id":"i1","texte":"« ô ami »"},{"id":"i2","texte":"« cette histoire est vraie, enfin presque »"},{"id":"i3","texte":"« très, très, très lente »"},{"id":"i4","texte":"« Écoute, ami »"}]},{"enonce":"Un élève termine son conte par : « Et depuis ce jour, cette tortue a une carapace. » Quelle erreur a-t-il faite ?","aide":"La situation finale d’un conte étiologique vaut pour toute l’espèce.","type":"choix","options":[{"id":"a","texte":"Il s’adresse directement au lecteur"},{"id":"b","texte":"Il écrit une situation finale claire"},{"id":"c","texte":"Il utilise le passé simple pour raconter"},{"id":"d","texte":"Il ne parle que d’une seule tortue"}],"multiple":false},{"enonce":"Remets les cartes d’écriture dans le bon ordre pour écrire ton conte.","aide":"On invente d’abord, on écrit ensuite, on conclut à la fin.","type":"ordre","items":[{"id":"a","texte":"Choisir une particularité animale"},{"id":"b","texte":"Finir par « et depuis ce jour… »"},{"id":"c","texte":"Inventer la faute"},{"id":"d","texte":"Inventer la sanction"},{"id":"e","texte":"Écrire au passé simple et à l’imparfait"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m96"]},"explication":"Les deux **ami** sont des **apostrophes** : le conteur parle directement au lecteur."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c1","i4":"c0"}},"explication":"**Apostrophe** : « Écoute, ami », « ô ami ». **Répétition** : « très, très, très », « Pfff ! ». **Humour** : « enfin presque »."},{"cle":{"type":"choix","ids":["d"]},"explication":"La fin doit valoir **pour toujours** et **pour toute l’espèce** : « toutes les tortues du monde portent leur maison »."},{"cle":{"type":"ordre","ids":["a","c","d","e","b"]},"explication":"D’abord l’animal, la faute et la sanction ; puis on écrit avec les bons temps ; enfin on clôt par **« et depuis ce jour… »**."}]$ex$::jsonb),
  ('ac165b13-446f-5097-bc4c-887ba7eef21e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le matin d’un dimanche, en quatre vers","competence":"analyser-texte","situation":"Ta classe a reçu un petit poème de quatre vers. Avant de le réciter, on veut en repérer les outils : la rime, la comparaison, la personnification.","documents":[{"id":"poeme","type":"texte","genre":"poeme","titre":"Dimanche","auteur":"Poème écrit pour l’exercice","blocs":["Le vent murmure dans les branches,","Le ciel est bleu comme un bonbon,","Les enfants courent, c’est dimanche,","Les oiseaux sifflent leur chanson."]}],"questions":[{"enonce":"Le deuxième vers rapproche le ciel d’un bonbon. Touche l’**outil de comparaison**.","aide":"C’est un petit mot qui relie les deux éléments : « comme », « tel », « semblable à »…","type":"zone","document":"poeme","multiple":false},{"enonce":"Touche les deux mots qui riment à la fin des vers 2 et 4.","aide":"Lis les deux fins de vers à voix haute : quel son se répète ?","type":"zone","document":"poeme","multiple":true},{"enonce":"Le poète prête au vent une action humaine. Touche les deux mots qui le montrent : le vent et ce qu’il fait.","aide":"Un vent qui « murmure » : qui peut murmurer, d’habitude ?","type":"zone","document":"poeme","multiple":true},{"enonce":"Les vers 1 et 3 riment aussi (« branches », « dimanche »). Quelle est la disposition des rimes ?","aide":"Note A pour la rime des vers 1 et 3, B pour celle des vers 2 et 4, puis lis la suite.","type":"choix","options":[{"id":"a","texte":"Embrassées : ABBA"},{"id":"b","texte":"Libres : aucune rime"},{"id":"c","texte":"Suivies : AABB"},{"id":"d","texte":"Croisées : ABAB"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"L’outil est **comme** : « bleu comme un bonbon » est une **comparaison**. Sans lui, ce serait une métaphore."},{"cle":{"type":"zone","ids":["m12","m23"]},"explication":"**bonbon** et **chanson** riment : on entend le même son [ɔ̃] à la fin des vers 2 et 4."},{"cle":{"type":"zone","ids":["m1","m2"]},"explication":"Le **vent** qui **murmure** : on prête à une chose un trait humain. C’est une **personnification**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Vers 1 : A (branches), vers 2 : B (bonbon), vers 3 : A (dimanche), vers 4 : B (chanson). Le schéma **ABAB** s’appelle les rimes **croisées**."}]$ex$::jsonb),
  ('ac165b13-446f-5097-bc4c-887ba7eef21e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La nuit, les étoiles et les toits","competence":"analyser-texte","situation":"Le poème que tu lis est écrit en vers libres. Tu dois y reconnaître des images : laquelle est une comparaison ? laquelle une métaphore ? laquelle une personnification ?","documents":[{"id":"nuit","type":"texte","genre":"poeme","titre":"La nuit","auteur":"Poème écrit pour l’exercice","blocs":["La nuit est un grand manteau noir ;","les étoiles dansent sans bruit ;","la lune, ronde comme une perle, brille sur les toits.","","Les arbres dorment debout,","le vent fredonne tout bas","et la rue est vide."]}],"questions":[{"enonce":"Le premier vers dit que la nuit **est** quelque chose, sans outil de comparaison. Touche le mot qui nomme cet objet.","aide":"Cherche ce que la nuit « est » au premier vers.","type":"zone","document":"nuit","multiple":false},{"enonce":"Pourquoi « La nuit est un grand manteau noir » n’est-il pas une comparaison ?","aide":"La différence entre comparaison et métaphore tient à un seul mot.","type":"choix","options":[{"id":"a","texte":"Il y a deux adjectifs de couleur"},{"id":"b","texte":"Il n’y a pas d’outil comme « comme »"},{"id":"c","texte":"Il y a un verbe conjugué"},{"id":"d","texte":"Il est placé au premier vers"}],"multiple":false},{"enonce":"Range chaque expression du poème selon l’image qu’elle contient.","aide":"Cherche l’outil de comparaison, puis demande-toi qui fait l’action : un arbre peut-il dormir ?","type":"categories","categories":[{"id":"c0","texte":"Comparaison"},{"id":"c1","texte":"Métaphore"},{"id":"c2","texte":"Personnification"}],"items":[{"id":"i0","texte":"Les arbres dorment debout"},{"id":"i1","texte":"Le vent fredonne tout bas"},{"id":"i2","texte":"La lune, ronde comme une perle"},{"id":"i3","texte":"La nuit est un grand manteau noir"}]},{"enonce":"Ce poème a deux groupes de trois vers. Comment s’appelle une strophe de trois vers ?","aide":"Le préfixe *ter-* rappelle le chiffre trois.","type":"choix","options":[{"id":"a","texte":"Un refrain"},{"id":"b","texte":"Un quatrain"},{"id":"c","texte":"Un distique"},{"id":"d","texte":"Un tercet"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"La nuit est un **manteau** : c’est une **métaphore**, car il n’y a pas d’outil de comparaison."},{"cle":{"type":"choix","ids":["b"]},"explication":"La comparaison utilise un **outil** (comme, tel, semblable à) ; la **métaphore** rapproche sans outil. Ici, il n’y en a pas."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c2","i2":"c0","i3":"c1"}},"explication":"**Métaphore** : la nuit est un manteau. **Comparaison** : « comme une perle ». **Personnification** : des arbres qui dorment et un vent qui fredonne agissent comme des humains."},{"cle":{"type":"choix","ids":["d"]},"explication":"Une strophe de trois vers est un **tercet** (distique : 2 vers ; quatrain : 4 vers)."}]$ex$::jsonb),
  ('ac165b13-446f-5097-bc4c-887ba7eef21e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le chat, la neige et un poème qui tombe","competence":"analyser-texte","situation":"Léo prépare un recueil pour la classe. Il hésite sur la disposition des rimes de son poème sur le chat, et il a eu une idée pour son poème sur la pluie. Aide-le.","documents":[{"id":"chat","type":"texte","genre":"poeme","titre":"Le chat","auteur":"Poème écrit pour l’exercice","blocs":["Le chat s’endort près de la fenêtre,","Dans le silence de la nuit,","Le vent siffle un peu puis s’enfuit,","Et le matin vient à renaître."]},{"id":"pluie","type":"texte","genre":"consigne","titre":"L’idée de Léo","blocs":["Léo écrit un poème sur la pluie. Il range les mots pour qu’ils dessinent des gouttes qui tombent sur la page."]}],"questions":[{"enonce":"Les vers 2 et 3 riment ensemble. Touche les deux mots qui riment.","aide":"Lis la fin des vers 2 et 3 à voix haute : tu entends le même son.","type":"zone","document":"chat","multiple":true},{"enonce":"Le vers 1 rime avec le vers 4, et le vers 2 avec le vers 3. Quel est le schéma de rimes ?","aide":"Note A pour la rime du vers 1, B pour celle du vers 2, puis continue.","type":"choix","options":[{"id":"a","texte":"ABAB : rimes croisées"},{"id":"b","texte":"ABCD : sans rimes"},{"id":"c","texte":"ABBA : rimes embrassées"},{"id":"d","texte":"AABB : rimes suivies"}],"multiple":false},{"enonce":"Le poème de Léo sur la pluie dessine son sujet avec la forme des mots. Comment appelle-t-on ce poème ?","aide":"La forme du poème dessine son sujet.","type":"choix","options":[{"id":"a","texte":"Une allitération"},{"id":"b","texte":"Un calligramme"},{"id":"c","texte":"Un quatrain"},{"id":"d","texte":"Un refrain"}],"multiple":false},{"enonce":"Léo dessine la pluie avec ses mots : c’est un calligramme. Quel poète est célèbre pour les siens ?","aide":"Il a publié le recueil *Calligrammes* en 1918.","type":"choix","options":[{"id":"a","texte":"Jean de La Fontaine"},{"id":"b","texte":"Guillaume Apollinaire"},{"id":"c","texte":"Victor Hugo"},{"id":"d","texte":"Paul Verlaine"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Depuis le XIXe siècle, les poètes s’affranchissent des règles du compte des syllabes.","type":"trous","segments":["Un vers libre ne compte pas un nombre ",0," de syllabes."],"banque":["fixe","impair","pair","petit"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m20","m21"]},"explication":"**nuit** et **s’enfuit** riment ensemble. Les vers 1 et 4 riment aussi (fenêtre, renaître)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Vers 1 : A (fenêtre), vers 2 : B (nuit), vers 3 : B (s’enfuit), vers 4 : A (renaître). Le schéma **ABBA** est celui des rimes **embrassées**."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est un **calligramme** : un poème dont la forme dessine son sujet."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Apollinaire** est célèbre pour ses calligrammes : des poèmes dont les mots dessinent ce qu’ils disent."},{"cle":{"type":"trous","trous":[["fixe"]]},"affichage":"fixe","explication":"Un vers libre ne compte pas un nombre **fixe** de syllabes : la contrainte disparaît, l’intention reste."}]$ex$::jsonb),
  ('64df3209-e4e8-548e-a89f-fb120625e366'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un poème qui parle à son jardin","competence":"analyser-texte","situation":"La poésie lyrique dit les sentiments du poète. Voici un poème écrit pour l’exercice : à toi de repérer ce qui rend ses sentiments si présents.","documents":[{"id":"jardin","type":"texte","genre":"poeme","titre":"Ô jardin","auteur":"Poème écrit pour l’exercice","blocs":["Ô jardin, que tu es beau !","Mon cœur bat dans tes allées.","Ô jardin, que tu es beau !","Mes joies y sont enlacées.","","Ô jardin, que tu es beau !","Je pleure quand vient l’hiver.","Ô jardin, que tu es beau !","Les feuilles quittent leur vert."]}],"questions":[{"enonce":"Dans la poésie lyrique, le poète parle de lui. Touche les trois mots de la **première personne** (je, mon, mes).","aide":"Cherche les mots qui désignent celui qui parle.","type":"zone","document":"jardin","multiple":true},{"enonce":"Combien de fois le vers « Ô jardin, que tu es beau ! » est-il écrit dans le poème ?","aide":"Compte-le dans chacune des deux strophes.","type":"nombre"},{"enonce":"Dans la deuxième strophe, quel sentiment le poète exprime-t-il ?","aide":"Relis le deuxième vers de la strophe : que fait le poète quand vient l’hiver ?","type":"choix","options":[{"id":"a","texte":"La colère"},{"id":"b","texte":"L’ennui profond"},{"id":"c","texte":"La tristesse"},{"id":"d","texte":"La peur"}],"multiple":false},{"enonce":"Que produit ce vers répété d’un bout à l’autre du poème ?","aide":"Pense aux refrains des chansons.","type":"choix","options":[{"id":"a","texte":"Une explication du texte"},{"id":"b","texte":"Un silence très long"},{"id":"c","texte":"Une mélodie, comme une chanson"},{"id":"d","texte":"Un changement de sujet"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m18","m29"]},"explication":"**Mon, Mes, Je** sont les marques de la première personne : ce sont les marques du lyrisme."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Ce vers est écrit **quatre fois** (deux fois par strophe) : c’est un **refrain**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il **pleure** quand vient l’hiver : il exprime sa **tristesse**. La poésie lyrique exprime des sentiments."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **refrain** installe une mélodie : le poème, comme à l’origine (la lyre), s’entend presque comme une chanson."}]$ex$::jsonb),
  ('64df3209-e4e8-548e-a89f-fb120625e366'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La glace qui craque et la chanson qui revient","competence":"analyser-texte","situation":"Deux textes sur la musique des mots : un poème où les sons imitent la glace qui se brise, et une chanson où un vers revient comme un refrain.","documents":[{"id":"glace","type":"texte","genre":"poeme","titre":"Sur l’étang gelé","auteur":"Poème écrit pour l’exercice","blocs":["Sous mes pas, la glace craque, croque, claque,","et le vent siffle sur le lac."]},{"id":"chanson","type":"texte","genre":"poeme","titre":"Reviens","auteur":"Chanson écrite pour l’exercice","blocs":["Chaque soir, je regarde la lune,","Ô étoile, dis-moi si tu l’as vue !","Reviens, reviens, mon bel été,","Reviens, reviens, reviens !"]}],"questions":[{"enonce":"Trois verbes de la glace répètent un même son consonne. Touche-les.","aide":"Lis le premier vers à voix haute : quel son entends-tu au début de chaque verbe ?","type":"zone","document":"glace","multiple":true},{"enonce":"Quel est l’effet de cette répétition de sons ?","aide":"Dis les trois verbes à voix haute : à quel bruit font-ils penser ?","type":"choix","options":[{"id":"a","texte":"Elle présente un nouveau personnage"},{"id":"b","texte":"Elle fait entendre la glace qui se brise"},{"id":"c","texte":"Elle ralentit le rythme du poème"},{"id":"d","texte":"Elle annonce la fin du poème"}],"multiple":false},{"enonce":"Dans la chanson, le poète s’adresse directement à quelqu’un grâce à « Ô ». Touche le mot qui nomme celui à qui il parle.","aide":"Regarde le deuxième vers, juste après le « Ô ».","type":"zone","document":"chanson","multiple":false},{"enonce":"Quel groupe de mots joue le rôle de refrain dans la chanson ?","aide":"Cherche ce qui se répète dans les deux derniers vers.","type":"choix","options":[{"id":"a","texte":"« si tu l’as vue »"},{"id":"b","texte":"« Ô étoile, dis-moi »"},{"id":"c","texte":"« Chaque soir, je regarde la lune »"},{"id":"d","texte":"« Reviens, reviens… »"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m6","m7"]},"explication":"**craque, croque, claque** répètent le son [k] : c’est une **allitération**."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est une **harmonie imitative** : les sonorités imitent ce que le texte décrit, ici la glace qui craque."},{"cle":{"type":"zone","ids":["m7"]},"explication":"Il parle à l’**étoile** : c’est une **apostrophe**, une marque du lyrisme."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le refrain est la partie qui **se répète** : « Reviens, reviens… ». Les chansons obéissent aux mêmes outils que les poèmes."}]$ex$::jsonb),
  ('64df3209-e4e8-548e-a89f-fb120625e366'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La flaque, le caillou et la voix","competence":"analyser-texte","situation":"Samia et Noé ont préparé un poème pour la fête de l’école. Il transforme deux objets de tous les jours. Ils discutent de la meilleure manière de le dire.","documents":[{"id":"flaque","type":"texte","genre":"poeme","titre":"Après la pluie","auteur":"Poème écrit pour l’exercice","blocs":["Une flaque est tombée du ciel :","c’est un miroir où passent les nuages.","Ce caillou rond, tout gris, tout seul,","est une planète qui a perdu son chemin."]},{"id":"sms","type":"dialogue","modele":"sms","titre":"Répétition du poème","participants":[{"nom":"Samia","emoji":"👧","cote":"gauche"},{"nom":"Noé","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Samia","texte":"J’ai lu le poème très vite, sans m’arrêter."},{"qui":"Noé","texte":"Moi, j’ai marqué une pause après chaque vers."},{"qui":"Samia","texte":"Et j’ai gardé le même volume tout du long."},{"qui":"Noé","texte":"J’ai détaché les images : « un miroir », puis « une planète »."}]}],"questions":[{"enonce":"Le poète regarde deux objets banals. Touche-les.","aide":"Ce sont deux petites choses qu’on voit dans la rue après la pluie.","type":"zone","document":"flaque","multiple":true},{"enonce":"Relie chaque objet à ce qu’il devient dans le poème.","aide":"Relis les vers 1 et 2 pour la flaque, les vers 3 et 4 pour le caillou.","type":"association","gauche":[{"id":"g0","texte":"La flaque"},{"id":"g1","texte":"Le caillou"}],"droite":[{"id":"d0","texte":"Une planète qui a perdu son chemin"},{"id":"d1","texte":"Un miroir où passent les nuages"}]},{"enonce":"Range ce que font Samia et Noé : est-ce une bonne façon de dire un poème ?","aide":"Rappelle-toi les trois conseils : respecter les pauses, détacher les images, varier le volume.","type":"categories","categories":[{"id":"c0","texte":"Bien dire un poème"},{"id":"c1","texte":"À éviter"}],"items":[{"id":"i0","texte":"Lire très vite, sans s’arrêter"},{"id":"i1","texte":"Garder le même volume tout du long"},{"id":"i2","texte":"Marquer une pause après chaque vers"},{"id":"i3","texte":"Détacher les images"}]},{"enonce":"Complète la définition.","aide":"Pense à la joie, à l’amour, à la tristesse, à l’émerveillement…","type":"trous","segments":["La poésie lyrique exprime des ",0,"."],"banque":["chiffres","recettes","lois","sentiments"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m15"]},"explication":"La **flaque** et le **caillou** sont des objets de tous les jours : le poète va en transformer le regard."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"La flaque devient **un miroir du ciel** et le caillou **une planète**. C’est le **regard** qui change, pas la chose."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Pour bien dire un poème : **respecter les pauses**, **détacher les images**, **varier le volume**. Lire d’une traite, au même volume, est à éviter."},{"cle":{"type":"trous","trous":[["sentiments","emotions"]]},"affichage":"sentiments","explication":"La poésie lyrique exprime des **sentiments** et cherche à les faire partager."}]$ex$::jsonb),
  ('5a396493-5b55-5ed9-8879-3481b3d8fdda'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un zèbre tout zébrouillé","competence":"comprendre-langue","situation":"Pour un concours de poèmes animaliers, tu lis un poème dans lequel un mot a été inventé. Il te faut comprendre comment on fabrique un mot-valise.","documents":[{"id":"zebre","type":"texte","genre":"poeme","titre":"Le zèbre","auteur":"Poème écrit pour l’exercice, à la manière des poèmes animaliers","blocs":["Un zèbre en pyjama rayé","se trompe de chemin :","il est tout zébrouillé,","perdu dans ses rayures !"]}],"questions":[{"enonce":"Un mot du poème n’existe pas dans le dictionnaire : il a été fabriqué en fondant deux mots en un. Touche-le.","aide":"Cherche un mot étrange qui ressemble à « zèbre ».","type":"zone","document":"zebre","multiple":false},{"enonce":"De quels deux mots est formé « zébrouillé » ?","aide":"Lis le mot à voix haute : on y entend le nom de l’animal puis un adjectif qui parle d’être perdu.","type":"choix","options":[{"id":"a","texte":"zébu et brouillard"},{"id":"b","texte":"zèbre et mouillé"},{"id":"c","texte":"zéro et brouillon"},{"id":"d","texte":"zèbre et embrouillé"}],"multiple":false},{"enonce":"Relie chaque jeu de langue à sa définition.","aide":"Commence par le mot-valise, que tu viens de rencontrer.","type":"association","gauche":[{"id":"g0","texte":"Le mot-valise"},{"id":"g1","texte":"Le calembour"},{"id":"g2","texte":"La paronymie"},{"id":"g3","texte":"Le détournement"}],"droite":[{"id":"d0","texte":"Rapprocher des mots qui se ressemblent"},{"id":"d1","texte":"Retourner un proverbe ou une expression figée"},{"id":"d2","texte":"Jouer sur deux sens ou deux sons proches"},{"id":"d3","texte":"Fondre deux mots en un"}]},{"enonce":"Complète le nom du groupe d’écrivains.","aide":"Les deux dernières lettres du sigle, PO, cachent le dernier mot.","type":"trous","segments":["OULIPO veut dire : OUvroir de LIttérature ",0,"."],"banque":["parlée","populaire","poétique","potentielle"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"**zébrouillé** est un **mot-valise** : il fond deux mots en un."},{"cle":{"type":"choix","ids":["d"]},"explication":"**zèbre + embrouillé** : le zèbre est perdu dans ses rayures, il est « zébrouillé »."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"Quatre jeux de langue du recueil : le **mot-valise**, le **calembour**, la **paronymie** et le **détournement**."},{"cle":{"type":"trous","trous":[["potentielle"]]},"affichage":"potentielle","explication":"L’**Oulipo** est l’**Ou**vroir de **Li**ttérature **Po**tentielle : un groupe d’écrivains qui s’imposent des contraintes d’écriture."}]$ex$::jsonb),
  ('5a396493-5b55-5ed9-8879-3481b3d8fdda'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le concours des ani-mots","competence":"comprendre-langue","situation":"La salle des fêtes organise un concours de jeux de mots sur les animaux. Quatre propositions sont affichées. Le jury doit reconnaître le jeu de langue de chacune.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Concours d’ani-mots","sousTitre":"Salle des fêtes — vendredi 18 h","emoji":"🐘","lignes":[{"texte":"1. « Un éléphant, ça trompe énormément. »","id":"z1"},{"texte":"2. « Le crocodocile : un crocodile très docile. »","id":"z2"},{"texte":"3. « Petit à petit, l’éléphant fait son nid. »","id":"z3"},{"texte":"4. « Poisson ou poison : attention au menu ! »","id":"z4"}],"pied":"Propositions écrites pour l’exercice","teinte":"violet"}],"questions":[{"enonce":"Quelle proposition joue sur deux sens du mot « trompe » ? Touche la ligne.","aide":"Un éléphant a une trompe ; mais on peut aussi tromper quelqu’un.","type":"zone","document":"affiche","multiple":false},{"enonce":"Quelle proposition contient un mot fabriqué en fondant deux mots ? Touche la ligne.","aide":"Cherche un mot inventé qui ressemble à deux mots de la phrase.","type":"zone","document":"affiche","multiple":false},{"enonce":"La ligne 3 retourne un proverbe. Quel est le proverbe de départ ?","aide":"Le proverbe parle d’un autre animal et de la même chose que « nid ».","type":"choix","options":[{"id":"a","texte":"« Petit à petit, l’oiseau fait son nid. »"},{"id":"b","texte":"« Tel père, tel fils. »"},{"id":"c","texte":"« Chat échaudé craint l’eau froide. »"},{"id":"d","texte":"« Qui se ressemble s’assemble. »"}],"multiple":false},{"enonce":"Relie chaque numéro de l’affiche au jeu de langue.","aide":"Poisson et poison se ressemblent beaucoup, mais ne veulent pas dire la même chose.","type":"association","gauche":[{"id":"g0","texte":"Ligne 1"},{"id":"g1","texte":"Ligne 2"},{"id":"g2","texte":"Ligne 3"},{"id":"g3","texte":"Ligne 4"}],"droite":[{"id":"d0","texte":"Paronymie"},{"id":"d1","texte":"Calembour"},{"id":"d2","texte":"Détournement"},{"id":"d3","texte":"Mot-valise"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La ligne **1** est un **calembour** : « trompe » est à la fois le nez de l’éléphant et le verbe tromper."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La ligne **2** : « crocodocile » fond **crocodile** et **docile** : c’est un **mot-valise**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le proverbe est « Petit à petit, **l’oiseau** fait son nid ». La ligne 3 le **détourne** en changeant l’animal."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"Ligne 1 : **calembour**. Ligne 2 : **mot-valise**. Ligne 3 : **détournement** d’un proverbe. Ligne 4 : **paronymie** (poisson / poison)."}]$ex$::jsonb),
  ('5a396493-5b55-5ed9-8879-3481b3d8fdda'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un lion sans « e » : écrire sous contrainte","competence":"manier-langue","situation":"Dans l’atelier d’écriture, on s’inspire de l’Oulipo. Tu reçois un texte écrit sous contrainte, où un seul mot a glissé par erreur, puis la fiche de la méthode.","documents":[{"id":"lion","type":"texte","genre":"recit","titre":"Le lion affamé","auteur":"Texte écrit pour l’exercice : lipogramme en e, avec un intrus","blocs":["Un gros lion a faim.","Il cherche un bon plat.","Il voit un mouton gras, il bondit, il mord.","Un gros plat, un bon plat, un plat chaud !"]},{"id":"methode","type":"texte","genre":"consigne","titre":"Atelier : un poème sur le morse","blocs":["Ta mission : écrire un poème sur un animal, le morse, sous contrainte. Voici les cartes de la méthode, en vrac.","A. Écrire.","B. Choisir l’animal.","C. S’imposer une contrainte.","D. Chercher tous les mots que son nom contient ou évoque."]}],"questions":[{"enonce":"Ce texte est un **lipogramme** : on n’y emploie jamais la lettre *e*. Un seul mot brise la contrainte. Touche-le.","aide":"Lis chaque mot lentement : lequel contient un *e* ?","type":"zone","document":"lion","multiple":false},{"enonce":"Relie chaque contrainte de l’Oulipo à ce qu’elle impose.","aide":"Le lipogramme, tu viens de le voir à l’œuvre dans le texte du lion.","type":"association","gauche":[{"id":"g0","texte":"Le lipogramme"},{"id":"g1","texte":"La méthode S + 7"},{"id":"g2","texte":"Le poème combinatoire"}],"droite":[{"id":"d0","texte":"Remplacer chaque nom par le septième qui le suit dans le dictionnaire"},{"id":"d1","texte":"N’employer aucun e"},{"id":"d2","texte":"Des vers qui se recombinent"}]},{"enonce":"Remets dans l’ordre les étapes de la méthode pour écrire sous contrainte.","aide":"Il faut un sujet avant de chercher des mots, et une règle avant d’écrire.","type":"ordre","items":[{"id":"a","texte":"Chercher les mots que son nom contient ou évoque"},{"id":"b","texte":"Écrire"},{"id":"c","texte":"Choisir l’animal"},{"id":"d","texte":"S’imposer une contrainte"}]},{"enonce":"À quoi sert une contrainte d’écriture selon l’Oulipo ?","aide":"Le cours dit que la contrainte n’empêche pas d’écrire.","type":"choix","options":[{"id":"a","texte":"Elle rend le texte plus facile à lire"},{"id":"b","texte":"Elle sert à écrire beaucoup plus vite"},{"id":"c","texte":"Elle oblige à trouver des idées neuves"},{"id":"d","texte":"Elle empêche d’écrire quoi que ce soit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"Le mot **cherche** contient un *e* : il brise la contrainte du lipogramme."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le **lipogramme** interdit une lettre, la méthode **S + 7** transforme les noms, le **poème combinatoire** recombine ses vers."},{"cle":{"type":"ordre","ids":["c","a","d","b"]},"explication":"On choisit l’animal (B), on cherche ses mots (D), on s’impose une contrainte (C), puis on **écrit** (A)."},{"cle":{"type":"choix","ids":["c"]},"explication":"La contrainte **oblige à trouver** ce qu’on n’aurait pas cherché : c’est elle qui fait surgir l’idée."}]$ex$::jsonb),
  ('663aaaa7-2515-599e-84c4-9184cf6eb0bd'::uuid, 1, 1, 5, 20, 4,
