  ('663aaaa7-2515-599e-84c4-9184cf6eb0bd'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Scapin invente une galère turque","competence":"analyser-texte","situation":"Voici une scène adaptée de la pièce : Scapin raconte à Géronte une histoire inventée, pour obtenir de l’argent. Lis-la comme un metteur en scène : qui parle, qui trompe, qui est trompé ?","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"La galère","auteur":"D’après Molière, Les Fourberies de Scapin, II, 7 (1671) — texte adapté pour l’exercice","blocs":[{"didascalie":"Scapin arrive, l’air affolé. Géronte l’écoute."},{"personnage":"Scapin","replique":"Ah, Monsieur, quel malheur ! Votre fils est prisonnier sur une galère turque !"},{"personnage":"Géronte","replique":"Que diable allait-il faire dans cette galère ?"},{"personnage":"Scapin","replique":"Il ne pensait pas être enlevé. Pour le libérer, il faut payer une rançon."},{"personnage":"Géronte","replique":"Que diable allait-il faire dans cette galère ?"},{"personnage":"Scapin","replique":"Vite, Monsieur, donnez-moi l’argent !"}]}],"questions":[{"enonce":"Scapin invente un lieu où le fils serait prisonnier. Touche ce mot dans **sa** première réplique.","aide":"C’est un navire, dans la première réplique de Scapin.","type":"zone","document":"scene","multiple":false},{"enonce":"Scapin fait semblant d’être bouleversé. Touche le mot de sa première réplique qui exprime ce faux chagrin.","aide":"Il crie « quel… ! » : cherche le nom qui suit.","type":"zone","document":"scene","multiple":false},{"enonce":"Combien de fois Géronte dit-il la phrase « Que diable allait-il faire dans cette galère ? »","aide":"Compte ses répliques.","type":"nombre"},{"enonce":"Pourquoi Scapin invente-t-il cette histoire ?","aide":"Regarde la dernière réplique de Scapin : que demande-t-il ?","type":"choix","options":[{"id":"a","texte":"Pour se faire pardonner"},{"id":"b","texte":"Pour faire peur au public"},{"id":"c","texte":"Pour sauver vraiment le fils"},{"id":"d","texte":"Pour soutirer de l’argent à Géronte"}],"multiple":false},{"enonce":"Qu’est-ce qui rend cette scène rapide et comique à lire à voix haute ?","aide":"Compte la longueur des répliques de Géronte.","type":"choix","options":[{"id":"a","texte":"De très longs discours de chaque acteur"},{"id":"b","texte":"Des chansons à chaque réplique"},{"id":"c","texte":"Des répliques courtes qui s’enchaînent vite"},{"id":"d","texte":"Un seul personnage qui parle tout seul"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"La **galère** turque est une invention de Scapin : chaque mensonge en appelle un autre."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**Malheur** : Scapin joue le désespoir pour que Géronte le croie."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Géronte la dit **deux fois**. Cette réplique est passée en proverbe."},{"cle":{"type":"choix","ids":["d"]},"explication":"Scapin ment pour **soutirer de l’argent** à Géronte, afin d’aider les jeunes gens."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le rythme est le cœur du comique : répliques **courtes**, qui s’enchaînent vite et se répètent en écho."}]$ex$::jsonb),
  ('663aaaa7-2515-599e-84c4-9184cf6eb0bd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le valet plus malin que ses maîtres","competence":"analyser-document","situation":"Pour ton exposé, tu rapproches la chaîne des mensonges de Scapin et le résumé de la scène du sac. Qui domine vraiment ?","documents":[{"id":"chaine","type":"chaine","titre":"Un mensonge en appelle un autre","disposition":"ligne","noeuds":[{"id":"z1","texte":"Un mariage forcé inventé","emoji":"💍"},{"id":"z2","texte":"?","emoji":"🗡️"},{"id":"z3","texte":"Une galère turque inventée","emoji":"⚓"}],"liens":[{"de":"z1","a":"z2","texte":"appelle"},{"de":"z2","a":"z3","texte":"appelle"}]},{"id":"sac","type":"texte","genre":"source","titre":"La scène du sac (acte III)","auteur":"Résumé écrit pour l’exercice, d’après Molière","blocs":["Scapin persuade Géronte de se cacher dans un sac pour échapper à des ennemis.","Puis il imite plusieurs voix d’ennemis qui cherchent le vieillard.","Enfin il roue le sac de coups, tout en prétendant sauver son maître."]}],"questions":[{"enonce":"Quel mensonge manque au milieu de la chaîne ?","aide":"Une personne inventée qui veut se venger, entre le mariage et la galère.","type":"choix","options":[{"id":"a","texte":"Un héritage perdu inventé"},{"id":"b","texte":"Un frère vengeur inventé"},{"id":"c","texte":"Un trésor caché inventé"},{"id":"d","texte":"Un naufrage en mer inventé"}],"multiple":false},{"enonce":"Remets dans l’ordre les étapes de la scène du sac.","aide":"Le texte du Doc 2 suit l’ordre de la scène.","type":"ordre","items":[{"id":"a","texte":"Il roue le sac de coups"},{"id":"b","texte":"Scapin persuade Géronte de se cacher dans un sac"},{"id":"c","texte":"Il imite plusieurs voix d’ennemis"}]},{"enonce":"Scapin frappe tout en faisant semblant de protéger son maître. Touche le mot du texte qui dit qu’il fait semblant.","aide":"Cherche le verbe qui veut dire « faire croire ».","type":"zone","document":"sac","multiple":false},{"enonce":"Dans cette pièce, qui est le plus intelligent ?","aide":"Pense au renversement : le valet mène, les maîtres suivent.","type":"choix","options":[{"id":"a","texte":"Le valet, Scapin, plus malin que ses maîtres"},{"id":"b","texte":"Les deux pères, toujours d’accord"},{"id":"c","texte":"Géronte, le maître, plus fin que son valet"},{"id":"d","texte":"Les jeunes gens amoureux"}],"multiple":false},{"enonce":"Relie chaque ancêtre du valet rusé à son théâtre d’origine.","aide":"Le zanni est italien.","type":"association","gauche":[{"id":"g0","texte":"L’esclave malin"},{"id":"g1","texte":"Le zanni"}],"droite":[{"id":"d0","texte":"La commedia dell’arte italienne"},{"id":"d1","texte":"La comédie latine"}]}]}$ex$::jsonb,
