  ('e77034bb-2c62-5e62-8c94-b3d3a29313a2'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le plan d’un théâtre, vu d’en haut","competence":"observer-schema","situation":"Zoé visite un théâtre avec sa classe. L’ouvreuse lui montre le plan de la salle, vu d’en haut. Elle doit retrouver les différents espaces.","documents":[{"id":"plan","type":"schema","titre":"Plan du théâtre (vu d’en haut)","largeur":320,"hauteur":250,"elements":[{"forme":"rect","x":20,"y":20,"l":60,"h":130,"teinte":"gris","motif":"hachures","id":"z1","zone":true},{"forme":"rect","x":240,"y":20,"l":60,"h":130,"teinte":"gris","motif":"hachures","id":"z2","zone":true},{"forme":"rect","x":80,"y":20,"l":160,"h":130,"teinte":"jaune","motif":"clair","id":"z3","zone":true},{"forme":"emoji","x":130,"y":85,"emoji":"🎭","taille":36},{"forme":"emoji","x":190,"y":85,"emoji":"🧑","taille":30},{"forme":"ligne","de":[20,160],"a":[300,160],"teinte":"encre"},{"forme":"rect","x":50,"y":180,"l":220,"h":60,"teinte":"bleu","motif":"clair","id":"z4","zone":true},{"forme":"emoji","x":90,"y":210,"emoji":"👥","taille":28},{"forme":"emoji","x":160,"y":210,"emoji":"👥","taille":28},{"forme":"emoji","x":230,"y":210,"emoji":"👥","taille":28}]}],"questions":[{"enonce":"Touche l’espace de jeu des acteurs : le **plateau**.","aide":"C’est la grande zone où l’on voit un masque de théâtre et un acteur.","type":"zone","document":"plan","multiple":false},{"enonce":"Touche les deux espaces cachés au public, de chaque côté du plateau : les **coulisses**.","aide":"Ils sont hachurés, à gauche et à droite du plateau.","type":"zone","document":"plan","multiple":true},{"enonce":"Touche la zone où s’installent les spectateurs.","aide":"Elle est en bas du plan, de l’autre côté du trait.","type":"zone","document":"plan","multiple":false},{"enonce":"Relie chaque mot à ce qu’il désigne.","aide":"Pense à ce que tu viens de toucher sur le plan.","type":"association","gauche":[{"id":"g0","texte":"Le plateau"},{"id":"g1","texte":"Les coulisses"},{"id":"g2","texte":"La mise en scène"}],"droite":[{"id":"d0","texte":"L’espace caché"},{"id":"d1","texte":"Le travail qui transforme le texte en spectacle"},{"id":"d2","texte":"L’espace de jeu"}]}]}$ex$::jsonb,
