  ('e77034bb-2c62-5e62-8c94-b3d3a29313a2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Fabriquer l’illusion : la fiche technique","competence":"lire-tableau","situation":"Le club théâtre du collège prépare un spectacle sur les marins. La fiche technique dit ce que chaque équipe prépare. Retrouve l’outil de l’illusion derrière chaque ligne.","documents":[{"id":"fiche","type":"tableau","titre":"Fiche technique du spectacle","colonnes":["Ce que prépare l’équipe","Effet voulu"],"lignes":[["Un grand drap bleu agité par deux élèves","On croit voir la mer"],["Une cape rouge et une barbe blanche en coton","On reconnaît le capitaine"],["Un projecteur qui s’éteint puis se rallume","Un éclair dans la nuit"],["Des vagues enregistrées","Une atmosphère de tempête"]],"enteteLignes":true,"source":"Fiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la case qui décrit l’emploi de la **lumière**.","aide":"Cherche ce qui s’éteint et se rallume.","type":"zone","document":"fiche","multiple":false},{"enonce":"Relie chaque ligne de la fiche à l’outil de l’illusion qu’elle utilise.","aide":"Pense à ce que chaque outil apporte : le lieu, le personnage, l’atmosphère…","type":"association","gauche":[{"id":"g0","texte":"Le drap bleu"},{"id":"g1","texte":"La cape et la barbe"},{"id":"g2","texte":"Le projecteur"},{"id":"g3","texte":"Les vagues enregistrées"}],"droite":[{"id":"d0","texte":"Le son et la musique"},{"id":"d1","texte":"Le décor et les accessoires"},{"id":"d2","texte":"Le costume et le maquillage"},{"id":"d3","texte":"La lumière"}]},{"enonce":"Les spectateurs savent que le drap n’est pas la mer, et pourtant ils y croient. Comment appelle-t-on cet accord ?","aide":"Le spectateur ne se laisse pas tromper : il accepte d’être trompé.","type":"choix","options":[{"id":"a","texte":"La convention théâtrale"},{"id":"b","texte":"La didascalie"},{"id":"c","texte":"L’ironie dramatique"},{"id":"d","texte":"La mise en scène"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le mot contient « scène ».","type":"trous","segments":["Le travail du metteur en scène s’appelle la ",0,"."],"banque":["tirade","coulisse","mise en scène","didascalie"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"La lumière isole, colore et rythme : ici, un projecteur qui s’éteint puis se rallume fait l’**éclair**."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"Le **décor** donne le lieu, le **costume** et le **maquillage** le personnage, la **lumière** isole et rythme, le **son** crée l’atmosphère."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est la **convention théâtrale** : le spectateur accepte de croire à ce qu’il voit, même en sachant que c’est un décor."},{"cle":{"type":"trous","trous":[["mise en scene"]]},"affichage":"mise en scène","explication":"La **mise en scène** est le travail qui transforme un texte en spectacle."}]$ex$::jsonb),
  ('e77034bb-2c62-5e62-8c94-b3d3a29313a2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le fantôme du grenier : qui sait quoi ?","competence":"analyser-texte","situation":"Dans la pièce de la classe, un valet joue la peur devant son maître. Le public sait la vérité, le maître l’ignore. Un second document compare deux affiches pour t’aider à trouver le genre de la pièce.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Le fantôme du grenier","auteur":"Scène écrite pour l’exercice","blocs":[{"didascalie":"Le plateau est dans la pénombre. Un drap blanc bouge derrière un fauteuil. Monsieur Bertrand, le maître, entre sans le voir."},{"personnage":"Pierrot","replique":"Monsieur, Monsieur ! J’ai vu un fantôme ! Je tremble de la tête aux pieds !"},{"personnage":"Monsieur Bertrand","replique":"Un fantôme ? Dans ma maison ? Quelle sottise !"},{"didascalie":"Le drap se lève : le public aperçoit un enfant qui retient son rire. Pierrot lui fait un clin d’œil."},{"personnage":"Monsieur Bertrand","replique":"Je ne vois rien. Tu rêves, Pierrot !"},{"didascalie":"À la fin, tout le monde rit et se réconcilie."}]},{"id":"affiches","type":"tableau","titre":"Deux pièces à l’affiche","colonnes":["Pièce","Personnages","Fin"],"lignes":[["Le Fantôme du grenier","Un valet, son maître, un enfant","Tout le monde rit et se réconcilie"],["La Chute du roi","Un roi illustre, pris dans un destin funeste","Le roi meurt"]],"enteteLignes":true,"source":"Affiches écrites pour l’exercice"}],"questions":[{"enonce":"Pierrot joue la peur devant son maître. Touche le verbe de sa réplique qui exprime cette fausse peur.","aide":"C’est ce que fait le corps quand on a très peur.","type":"zone","document":"scene","multiple":false},{"enonce":"Qui ignore que le « fantôme » est un enfant sous un drap ?","aide":"Le public voit l’enfant grâce à une didascalie : qui ne le voit pas ?","type":"choix","options":[{"id":"a","texte":"Monsieur Bertrand"},{"id":"b","texte":"Pierrot, le valet"},{"id":"c","texte":"L’enfant caché"},{"id":"d","texte":"Le public entier"}],"multiple":false},{"enonce":"Comment appelle-t-on ce décalage entre ce que sait le spectateur et ce que ignore un personnage ?","aide":"Le spectateur en sait plus que le personnage.","type":"choix","options":[{"id":"a","texte":"La tragédie"},{"id":"b","texte":"L’ironie dramatique"},{"id":"c","texte":"La convention théâtrale"},{"id":"d","texte":"Le monologue"}],"multiple":false},{"enonce":"Range ces traits selon qu’ils décrivent une comédie ou une tragédie.","aide":"Regarde les deux lignes du tableau des affiches.","type":"categories","categories":[{"id":"c0","texte":"Comédie"},{"id":"c1","texte":"Tragédie"}],"items":[{"id":"i0","texte":"Elle finit mal"},{"id":"i1","texte":"Elle finit bien"},{"id":"i2","texte":"Des personnages illustres pris dans un destin funeste"},{"id":"i3","texte":"Des personnages ordinaires"}]},{"enonce":"À quel genre appartient *Le Fantôme du grenier* ?","aide":"Regarde ses personnages et sa fin dans le tableau.","type":"choix","options":[{"id":"a","texte":"À aucun genre"},{"id":"b","texte":"À la comédie"},{"id":"c","texte":"Aux deux"},{"id":"d","texte":"À la tragédie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"**tremble** : Pierrot fait semblant d’avoir peur. C’est du théâtre dans le théâtre : deux niveaux."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Monsieur Bertrand** ne voit rien, alors que le public et Pierrot savent la vérité."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est l’**ironie dramatique** : une grande source de plaisir pour le public."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"La **comédie** met en scène des personnages ordinaires et finit **bien** ; la **tragédie**, des personnages illustres, et finit **mal**."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est une **comédie** : personnages ordinaires, et tout finit bien."}]$ex$::jsonb),
