   $ex${"titre":"Une scène presque dans le noir","competence":"analyser-texte","situation":"Voici une scène écrite pour l’exercice, à la manière d’une réécriture théâtrale du conte : une petite fille, sa mère, et un danger qu’on ne voit pas. Lis comme un metteur en scène.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"La petite fille et le noir","auteur":"Scène écrite pour l’exercice, à la manière d’une réécriture théâtrale du conte","blocs":[{"didascalie":"Le plateau est presque noir. Un faisceau de lumière éclaire une petite fille assise seule sur une chaise."},{"personnage":"Le narrateur","replique":"Il était une fois une enfant qui s’ennuyait dans une maison trop calme."},{"personnage":"La petite fille","replique":"Maman, je peux sortir ?"},{"personnage":"La mère","replique":"Pas maintenant, j’ai du travail."},{"didascalie":"Une ombre passe au fond. On entend une voix grave, très loin. On ne voit personne."}]}],"questions":[{"enonce":"Le danger n’est jamais montré en entier. Touche les deux mots de la dernière didascalie qui le suggèrent.","aide":"Une chose qu’on voit passer et une chose qu’on entend.","type":"zone","document":"scene","multiple":true},{"enonce":"Comment les personnages sont-ils désignés dans la scène ?","aide":"Regarde les noms qui précèdent chaque réplique.","type":"choix","options":[{"id":"a","texte":"Par un simple numéro d’ordre"},{"id":"b","texte":"Par un prénom, comme dans la vie"},{"id":"c","texte":"Par leur rôle : « la mère »"},{"id":"d","texte":"Par un surnom très comique"}],"multiple":false},{"enonce":"Quel personnage vient raconter et commenter l’histoire sur scène ?","aide":"Il parle au présent de la scène, mais raconte au passé.","type":"choix","options":[{"id":"a","texte":"La grand-mère"},{"id":"b","texte":"Le narrateur"},{"id":"c","texte":"La mère"},{"id":"d","texte":"Le loup"}],"multiple":false},{"enonce":"D’où vient la peur dans cette scène ?","aide":"Pense au rôle de la lumière dans la première didascalie.","type":"choix","options":[{"id":"a","texte":"D’un monstre très visible"},{"id":"b","texte":"De costumes effrayants"},{"id":"c","texte":"De ce qu’on ne voit pas"},{"id":"d","texte":"De cris très forts"}],"multiple":false}]}$ex$::jsonb,
