  ('fd7d8ba4-d56d-5ba6-990f-6b6f69cbb3ae'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Trois spectateurs, un seul a bien regardé","competence":"argumenter","situation":"À la sortie du spectacle, trois élèves donnent leur avis. Un seul décrit juste. Utilise aussi la chaîne du thème de la pièce pour conclure.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Après le spectacle","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"},{"nom":"Zoé","emoji":"🧒","cote":"gauche"}],"repliques":[{"qui":"Lina","texte":"C’est une parodie du conte : ils exagèrent pour nous faire rire !"},{"qui":"Hugo","texte":"Pas du tout : j’ai surtout remarqué le noir. Le loup, on le devine à une ombre ou à une voix."},{"qui":"Zoé","texte":"Moi, j’ai remarqué que les personnages n’ont pas de prénom : « la petite fille », « la mère »."}]},{"id":"theme","type":"chaine","titre":"Le thème de la pièce : l’enfance qui grandit","disposition":"ligne","noeuds":[{"id":"z1","texte":"Quitter la maison"},{"id":"z2","texte":"Désobéir"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Revenir changé"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Pourquoi Lina se trompe-t-elle ?","aide":"Rappelle-toi la différence entre réécrire, adapter et parodier.","type":"choix","options":[{"id":"a","texte":"Pommerat adapte le conte, mais sans parodie"},{"id":"b","texte":"Il n’y a pas de loup dans toute la pièce"},{"id":"c","texte":"Le spectacle ne contient aucun narrateur"},{"id":"d","texte":"Pommerat n’a rien changé au conte de départ"}],"multiple":false},{"enonce":"Hugo explique comment on devine le loup sans le voir. Touche les deux mots qu’il emploie.","aide":"Une chose qu’on voit à peine, une chose qu’on entend.","type":"zone","document":"sms","multiple":true},{"enonce":"Quelle étape manque au milieu de la chaîne du thème ?","aide":"Entre désobéir et revenir changé, l’enfant traverse une épreuve.","type":"choix","options":[{"id":"a","texte":"Oublier le conte"},{"id":"b","texte":"Écouter les inconnus"},{"id":"c","texte":"Affronter la peur"},{"id":"d","texte":"Rester à la maison"}],"multiple":false},{"enonce":"Sur quoi Pommerat déplace-t-il l’accent du conte ?","aide":"Il s’éloigne de la morale explicite du conte.","type":"choix","options":[{"id":"a","texte":"La solitude de l’enfant et son désir d’aventure"},{"id":"b","texte":"Le comique des gros mots"},{"id":"c","texte":"Une morale : « n’écoutez pas les inconnus »"},{"id":"d","texte":"La vie du chasseur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"Pommerat **réécrit** et **adapte** ; il ne **parodie pas**. Parodier, c’est imiter en exagérant pour faire rire, et son texte est grave."},{"cle":{"type":"zone","ids":["m28","m32"]},"explication":"Le loup est souvent une **ombre**, une **voix**, une silhouette : la peur naît de ce qu’on ne voit pas."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’enfance qui grandit : quitter la maison → désobéir → **affronter la peur** → revenir changé."},{"cle":{"type":"choix","ids":["a"]},"explication":"Il déplace l’accent de la morale vers la **solitude** de l’enfant et son **désir d’aventure**."}]$ex$::jsonb),
  ('2b58a6c6-e44d-5f29-b556-1b1d91239d83'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un village où l’on ne repart plus","competence":"analyser-texte","situation":"Nour vit dans un village du Croissant fertile, à l’époque de la révolution néolithique. Lis un récit de sa famille : tu vas relever ce qu’elle cultive, ce qu’elle élève et ce qui a changé dans sa vie.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Une année chez Nour","auteur":"Texte écrit pour l’exercice","blocs":["Dans ce village du Croissant fertile, la famille de Nour ne se déplace plus. Au printemps, elle sème du blé, de l’orge et des lentilles.","Dans l’enclos, des moutons et des chèvres ont été domestiqués par ses grands-parents. Après la récolte, le grain est rangé dans le grenier, au sec.","Les hommes et les femmes du village restent près des champs et des troupeaux : il faut les surveiller toute l’année."]}],"questions":[{"enonce":"Touche, dans le récit, **les trois plantes** que la famille de Nour cultive.","aide":"Cherche ce que la famille sème au printemps.","type":"zone","document":"recit","multiple":true},{"enonce":"Touche **les deux animaux** que la famille élève dans l’enclos.","aide":"Ce sont des animaux domestiqués par les grands-parents de Nour.","type":"zone","document":"recit","multiple":true},{"enonce":"Complète la phrase avec le bon mot.","aide":"Regarde le dernier paragraphe : la famille ne se déplace plus.","type":"trous","segments":["Rester au même endroit pour surveiller champs et troupeaux, c’est la ",0,"."],"banque":["chasse","migration","domestication","sédentarisation"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19","m22","m25"]},"explication":"Les premiers champs du Néolithique donnent du **blé**, de l’**orge** et des **lentilles**."},{"cle":{"type":"zone","ids":["m30","m33"]},"explication":"Les **moutons** et les **chèvres** sont parmi les premiers animaux domestiqués."},{"cle":{"type":"trous","trous":[["sedentarisation"]]},"affichage":"sédentarisation","explication":"Produire sa nourriture oblige à rester sur place : c’est la **sédentarisation**. Elle donne les premiers villages permanents."}]$ex$::jsonb),
