   $ex${"titre":"Du Proche-Orient à l’Europe","competence":"se-reperer-temps","situation":"Léo prépare un exposé sur le Néolithique. Il a une frise pour dater le phénomène et un tableau pour comprendre ce que l’agriculture a changé.","documents":[{"id":"frise","type":"frise","titre":"Le Néolithique se répand","debut":-10000,"fin":-2000,"pas":1000,"source":"Dates approximatives.","periodes":[{"id":"z1","debut":-7000,"fin":-3000,"nom":"Néolithique en Europe","teinte":"vert"}],"evenements":[{"id":"z2","date":-10000,"nom":"Proche-Orient"},{"id":"z3","date":-7000,"nom":"Arrivée en Europe"}]},{"id":"chaine","type":"tableau","titre":"Les conséquences de l’agriculture","source":"D’après le cours.","colonnes":["La conséquence","Ce qu’elle entraîne"],"lignes":[["Des surplus","On stocke des réserves"],["Une population en hausse","?"],["Une spécialisation","Potiers, tisserands, forgerons"]],"enteteLignes":true}],"questions":[{"enonce":"Touche sur la frise la période pendant laquelle le Néolithique gagne **l’Europe**.","aide":"Cherche la bande de couleur qui porte le nom de l’Europe.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le début au Proche-Orient (vers −10 000) de l’arrivée en Europe (vers −7000) ?","aide":"Les deux dates sont avant J.-C. : soustrais la plus petite à la plus grande.","type":"nombre","unite":"ans"},{"enonce":"Complète la case « ? » du tableau.","aide":"Relis la ligne « Une population en hausse » : plus de nourriture donne plus de…","type":"trous","segments":["Quand il y a plus de nourriture, il y a plus d’",0,"."],"banque":["humains","villages","animaux","outils"]},{"enonce":"Associe chaque spécialiste à ce qu’il fabrique.","aide":"Pense au nom du métier : le potier fait des pots…","type":"association","gauche":[{"id":"g0","texte":"Le potier"},{"id":"g1","texte":"Le tisserand"},{"id":"g2","texte":"Le forgeron"}],"droite":[{"id":"d0","texte":"Des tissus"},{"id":"d1","texte":"Des vases en argile"},{"id":"d2","texte":"Des objets en métal"}]}]}$ex$::jsonb,
