  ('37f2fa20-b39b-54b2-8e0f-f66709d451a9'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Dumuzi découvre le métier de scribe","competence":"analyser-texte","situation":"À Uruk, un garçon de douze ans rend visite à son oncle au temple. Lis leur conversation et vérifie les comptes de la tablette qu’il lui montre.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Une matinée au temple","auteur":"Texte écrit pour l’exercice","blocs":["À Uruk, Dumuzi a douze ans. Son oncle est scribe au temple. Un matin, il lui montre une tablette d’argile encore fraîche.","« Regarde, dit l’oncle. Avec ce calame, j’imprime des signes en forme de coins. Ce matin, j’ai noté les sacs d’orge arrivés au temple. »","Dumuzi est étonné : dans son quartier, presque personne ne sait écrire. « C’est pour cela qu’on m’écoute, dit l’oncle. Celui qui sait compter et écrire aide le roi à gouverner. »"]},{"id":"comptes","type":"tableau","titre":"La tablette de l’oncle","source":"Chiffres écrits pour l’exercice.","colonnes":["Moment","Sacs d’orge reçus"],"lignes":[["Matin",45],["Midi",30],["Soir",25]],"enteteLignes":true}],"questions":[{"enonce":"Touche, dans le récit, **le mot qui nomme le métier** de l’oncle.","aide":"Cherche le premier paragraphe : quel est son travail au temple ?","type":"zone","document":"recit","multiple":false},{"enonce":"Touche **l’outil** avec lequel on écrit sur l’argile fraîche.","aide":"L’oncle le tient dans sa main pour imprimer les signes.","type":"zone","document":"recit","multiple":false},{"enonce":"Combien de sacs d’orge sont notés **en tout** sur la tablette ?","aide":"Additionne les trois lignes du tableau.","type":"nombre","unite":"sacs"},{"enonce":"Pourquoi l’oncle de Dumuzi est-il écouté dans la cité ?","aide":"Relis ce que dit l’oncle à la fin du récit.","type":"choix","options":[{"id":"a","texte":"Il est le plus grand paysan du quartier"},{"id":"b","texte":"Savoir écrire et compter donne du pouvoir"},{"id":"c","texte":"Il est le chef de l’armée du roi"},{"id":"d","texte":"Il possède tous les champs de la cité"}],"multiple":false}]}$ex$::jsonb,
