   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"L’**acropole** est la ville haute : on y construit les temples, comme le Parthénon à Athènes."},{"cle":{"type":"zone","ids":["z2"]},"explication":"L’**agora** est la place publique : marché et lieu de débat."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"L’acropole porte les **temples**, l’agora sert au **marché et aux débats**, la campagne **nourrit** la ville, et la communauté de **citoyens** fait la cité."},{"cle":{"type":"choix","ids":["b"]},"explication":"La Grèce antique est une **poussière de cités indépendantes**, qui se font la guerre tout en se sachant grecques."}]$ex$::jsonb),
  ('a6649dcc-ab84-5313-aa72-9c6129ad3fed'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une colonie à l’autre bout de la mer","competence":"analyser-document","situation":"Vers 600 av. J.-C., des Grecs fondent une nouvelle cité très loin de chez eux, sur la côte de la Gaule. L’un d’eux écrit une lettre à sa famille.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un colon","auteur":"Texte écrit pour l’exercice","blocs":["Chers parents, nous manquions de terres chez nous, alors nous avons traversé la mer. Notre nouvelle cité, Massalia, est belle.","Chaque année, nous envoyons une offrande aux dieux de notre cité mère, et nos bateaux chargés d’huile et de vin reviennent vers vous.","Les gens du pays ne parlent pas grec : pour nous, ce sont des « Barbares », c’est-à-dire des gens qui ne parlent pas notre langue."]},{"id":"carte","type":"carte","titre":"De la Grèce à la Gaule","fond":"mediterranee","cadrage":[-6,34,30,46],"source":"Carte simplifiée.","lieux":[{"id":"z1","lieu":"athenes","nom":"Athènes","symbole":"point","teinte":"violet"},{"id":"z2","lieu":"massalia","nom":"Massalia","symbole":"etoile","teinte":"ambre"}]},{"id":"frise","type":"frise","titre":"Deux dates","debut":-800,"fin":-500,"pas":100,"source":"Dates traditionnelles.","evenements":[{"id":"z3","date":-776,"nom":"Premiers Jeux"},{"id":"z4","date":-600,"nom":"Massalia"}]}],"questions":[{"enonce":"Touche **Massalia**, la colonie dont parle la lettre (aujourd’hui Marseille).","aide":"Elle est très à l’ouest de la Grèce, sur la côte de la Gaule.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche, dans la lettre, **les deux mots** qui montrent que la colonie garde des liens avec sa cité mère.","aide":"Un lien religieux et un lien commercial : cherche ce qu’on envoie aux dieux et ce qui revient en bateau.","type":"zone","document":"lettre","multiple":true},{"enonce":"Combien d’années séparent les premiers Jeux olympiques (−776) de la fondation de Massalia (−600) ?","aide":"Les deux dates sont avant J.-C. : soustrais la plus petite à la plus grande.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi ce colon et sa famille ont-ils quitté leur cité ?","aide":"Relis la première phrase de la lettre.","type":"choix","options":[{"id":"a","texte":"Ils étaient chassés par leurs dieux"},{"id":"b","texte":"Ils fuyaient une invasion perse"},{"id":"c","texte":"Ils voulaient fonder un grand empire"},{"id":"d","texte":"Ils manquaient de terres chez eux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Massalia** est l’actuelle Marseille, fondée vers 600 av. J.-C. : une colonie grecque en Gaule."},{"cle":{"type":"zone","ids":["m25","m34"]},"explication":"L’**offrande** aux dieux est un lien religieux ; les **bateaux** qui reviennent chargés sont un lien commercial."},{"cle":{"type":"nombre","valeur":176,"tolerance":0},"affichage":"176 ans","explication":"776 − 600 = **176 ans**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les cités grecques fondent des colonies **par manque de terres**."}]$ex$::jsonb),
  ('beace87c-920d-5f74-a684-77bac0549bd0'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Jour de fête à l’acropole","competence":"analyser-texte","situation":"C’est le jour des Panathénées, à Athènes. Phila et son père montent à l’acropole avec toute la cité. Lis le récit de cette fête pour comprendre comment les Grecs honoraient leurs dieux.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Les Panathénées","auteur":"Texte écrit pour l’exercice","blocs":["C’est jour de fête à Athènes. Phila et son père montent à l’acropole avec la procession. Ils apportent une offrande pour Athéna, la déesse protectrice de leur cité.","Devant le Parthénon, un prêtre sacrifie un animal sur l’autel. La viande sera partagée entre tous. Les fidèles restent dehors, car le temple est la maison de la déesse.","À l’intérieur du temple, il y a la grande statue d’Athéna."]}],"questions":[{"enonce":"Touche, dans le récit, **le lieu où l’on sacrifie** l’animal.","aide":"Cherche où le prêtre dépose l’animal, devant le temple.","type":"zone","document":"recit","multiple":false},{"enonce":"Touche ce que **le temple abrite** : le « corps » de la déesse.","aide":"Lis la dernière phrase : qu’y a-t-il à l’intérieur ?","type":"zone","document":"recit","multiple":false},{"enonce":"Où se déroulent les cérémonies d’après le récit ?","aide":"Relis le deuxième paragraphe : où restent les fidèles ?","type":"choix","options":[{"id":"a","texte":"Dans la maison de chaque fidèle"},{"id":"b","texte":"Dans la grande salle du temple"},{"id":"c","texte":"Dehors, devant le temple"},{"id":"d","texte":"Sur le mont Olympe"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"La fête se passe dans la cité d’Athéna.","type":"trous","segments":["Athéna est la déesse qui protège la cité d’",0,"."],"banque":["Sparte","Athènes","Delphes","Corinthe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m40"]},"explication":"Le sacrifice a lieu sur l’**autel**, dehors, devant le temple. La viande est ensuite partagée."},{"cle":{"type":"zone","ids":["m70"]},"explication":"Le temple abrite la **statue** de la déesse : c’est sa maison."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le temple n’est **pas** un lieu de rassemblement : les cérémonies se déroulent **dehors**, devant l’autel."},{"cle":{"type":"trous","trous":[["athenes"]]},"affichage":"Athènes","explication":"Athéna protège **Athènes**. Les Panathénées sont sa fête."}]$ex$::jsonb),
  ('beace87c-920d-5f74-a684-77bac0549bd0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"À chacun son dieu","competence":"analyser-document","situation":"Quatre Grecs prient aujourd’hui. Chacun s’adresse au dieu qui s’occupe de sa vie. Lis le récit puis aide-toi du tableau pour retrouver leurs dieux.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Quatre prières","auteur":"Texte écrit pour l’exercice","blocs":["Eudoxe, marin, part en mer au lever du jour. Il verse du vin sur le sol pour demander une traversée tranquille au dieu de la mer.","Lyra, paysanne, dépose du blé sur un petit autel : elle demande une bonne récolte à la déesse de l’agriculture.","Kléon, forgeron, fait une offrande avant d’allumer son feu : il honore le dieu de la forge.","Mélitta, actrice, joue une pièce de théâtre pendant la fête du dieu de la vigne."]},{"id":"dieux","type":"tableau","titre":"Quelques dieux de l’Olympe","source":"D’après le cours.","colonnes":["Le dieu","Son domaine"],"lignes":[["Dionysos","La vigne, le théâtre"],["Héphaïstos","La forge"],["Zeus","Roi des dieux, le ciel"],["Poséidon","La mer"],["Déméter","L’agriculture"],["Artémis","La chasse"]],"enteteLignes":true}],"questions":[{"enonce":"Touche **les quatre métiers** des personnages.","aide":"Chaque prénom est suivi de son métier.","type":"zone","document":"recit","multiple":true},{"enonce":"Associe chaque personnage au dieu qu’il prie.","aide":"Cherche dans le tableau le domaine qui correspond à chaque prière.","type":"association","gauche":[{"id":"g0","texte":"Eudoxe, le marin"},{"id":"g1","texte":"Lyra, la paysanne"},{"id":"g2","texte":"Kléon, le forgeron"},{"id":"g3","texte":"Mélitta, l’actrice"}],"droite":[{"id":"d0","texte":"Déméter"},{"id":"d1","texte":"Héphaïstos"},{"id":"d2","texte":"Poséidon"},{"id":"d3","texte":"Dionysos"}]},{"enonce":"Que montre le fait que chacun prie un dieu différent ?","aide":"Combien de dieux différents le tableau et le récit nomment-ils ?","type":"choix","options":[{"id":"a","texte":"Les Grecs prient en réalité un seul dieu sous quatre noms"},{"id":"b","texte":"Les Grecs ne croient pas du tout à leurs propres dieux"},{"id":"c","texte":"Seuls les gens riches ont le droit d’adresser des prières"},{"id":"d","texte":"Les Grecs ont plusieurs dieux : c’est le polythéisme"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le tableau s’intitule « dieux de l’… ».","type":"trous","segments":["Les douze principaux dieux grecs siègent sur le mont ",0,"."],"banque":["Sinaï","Palatin","Olympe","Parnasse"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m27","m47","m64"]},"explication":"Le **marin**, la **paysanne**, le **forgeron** et l’**actrice** prient chacun un dieu différent."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"**Poséidon** règne sur la mer, **Déméter** sur l’agriculture, **Héphaïstos** sur la forge, **Dionysos** sur la vigne et le théâtre."},{"cle":{"type":"choix","ids":["d"]},"explication":"Une religion qui a **plusieurs dieux** est **polythéiste**. Chaque dieu a son domaine."},{"cle":{"type":"trous","trous":[["olympe"]]},"affichage":"Olympe","explication":"Les douze principaux dieux siègent sur le mont **Olympe**."}]$ex$::jsonb),
  ('beace87c-920d-5f74-a684-77bac0549bd0'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un dieu en colère, une maison pour le dieu","competence":"analyser-document","situation":"Un récit d’Homère montre un dieu bien humain. Un plan de sanctuaire montre où les Grecs l’honorent. Croise les deux documents.","documents":[{"id":"iliade","type":"texte","genre":"source","titre":"Apollon et la maladie","auteur":"D’après l’Iliade d’Homère (début du chant I), texte très abrégé et adapté","blocs":["Le prêtre d’Apollon demande au roi Agamemnon de lui rendre sa fille, prisonnière des Grecs. Le roi refuse et chasse le prêtre.","Le prêtre prie son dieu. Apollon, furieux, descend de l’Olympe et envoie une maladie sur l’armée grecque.","Ce ne sont pas seulement le roi et ses chefs qui souffrent : des soldats meurent."]},{"id":"sanctuaire","type":"schema","titre":"Plan d’un sanctuaire","largeur":340,"hauteur":250,"source":"Plan simplifié, écrit pour l’exercice.","elements":[{"forme":"rect","x":8,"y":8,"l":324,"h":234,"arrondi":12,"teinte":"sable","motif":"clair"},{"forme":"polygone","points":[[80,34],[170,12],[260,34]],"teinte":"ambre","motif":"plein"},{"forme":"rect","x":90,"y":34,"l":160,"h":66,"teinte":"blanc","motif":"plein"},{"forme":"rect","x":124,"y":44,"l":92,"h":46,"teinte":"gris","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":170,"cy":55,"r":6,"teinte":"ambre","motif":"plein"},{"forme":"rect","x":162,"y":61,"l":16,"h":26,"arrondi":3,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":96,"cy":104,"r":5,"teinte":"gris","motif":"plein"},{"forme":"cercle","cx":118,"cy":104,"r":5,"teinte":"gris","motif":"plein"},{"forme":"cercle","cx":140,"cy":104,"r":5,"teinte":"gris","motif":"plein"},{"forme":"cercle","cx":200,"cy":104,"r":5,"teinte":"gris","motif":"plein"},{"forme":"cercle","cx":222,"cy":104,"r":5,"teinte":"gris","motif":"plein"},{"forme":"cercle","cx":244,"cy":104,"r":5,"teinte":"gris","motif":"plein"},{"forme":"rect","x":150,"y":150,"l":40,"h":26,"arrondi":3,"teinte":"brun","motif":"plein","id":"z2","zone":true},{"forme":"emoji","x":170,"y":144,"emoji":"🔥","taille":22},{"forme":"emoji","x":60,"y":206,"emoji":"🧑","taille":24},{"forme":"emoji","x":120,"y":214,"emoji":"🧑‍🦱","taille":24},{"forme":"emoji","x":220,"y":214,"emoji":"👩","taille":24},{"forme":"emoji","x":280,"y":206,"emoji":"🧔","taille":24},{"forme":"ligne","de":[170,190],"a":[170,180],"teinte":"brun","fleche":"fin"}]}],"questions":[{"enonce":"Touche, dans le récit, **le mot qui montre un sentiment humain** chez Apollon.","aide":"Un dieu grec peut avoir les mêmes sentiments que nous : colère, jalousie, vengeance…","type":"zone","document":"iliade","multiple":false},{"enonce":"Qu’est-ce qui distingue Apollon d’un simple mortel, d’après ce que tu sais des dieux grecs ?","aide":"Dans le récit, Apollon fait mourir des soldats qui n’ont rien fait.","type":"choix","options":[{"id":"a","texte":"Sa bonté : il protège toujours les innocents"},{"id":"b","texte":"Sa pauvreté : il vit comme les mortels"},{"id":"c","texte":"Sa sagesse : il ne se met jamais en colère"},{"id":"d","texte":"Son immortalité et sa puissance, pas sa vertu"}],"multiple":false},{"enonce":"Touche **l’autel**, devant le temple, où l’on sacrifie un animal.","aide":"Les fidèles sont dehors : l’autel est à l’extérieur du bâtiment.","type":"zone","document":"sanctuaire","multiple":false},{"enonce":"Touche **la salle intérieure** du temple, où se trouve la statue du dieu.","aide":"Cherche la petite pièce au centre du bâtiment, où se dresse une silhouette.","type":"zone","document":"sanctuaire","multiple":false},{"enonce":"Dieu ou héros ? Classe chaque nom.","aide":"Les héros sont entre les dieux et les hommes : ils accomplissent des exploits.","type":"categories","categories":[{"id":"c0","texte":"Dieu"},{"id":"c1","texte":"Héros"}],"items":[{"id":"i0","texte":"Poséidon"},{"id":"i1","texte":"Héraclès"},{"id":"i2","texte":"Athéna"},{"id":"i3","texte":"Achille"},{"id":"i4","texte":"Zeus"},{"id":"i5","texte":"Ulysse"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"Apollon est **furieux** : les dieux grecs ont des sentiments humains."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les dieux grecs diffèrent des mortels par l’**immortalité** et la **puissance**, pas par la vertu : un dieu peut être injuste."},{"cle":{"type":"zone","ids":["z2"]},"explication":"L’**autel** est dehors, devant le temple. Les fidèles y assistent aux cérémonies."},{"cle":{"type":"zone","ids":["z1"]},"explication":"Le temple est la **maison du dieu** : sa salle intérieure abrite la statue. Les fidèles restent dehors."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Zeus, Athéna et Poséidon sont des **dieux** ; Héraclès, Achille et Ulysse sont des **héros**, souvent nés d’un dieu et d’une mortelle."}]$ex$::jsonb),
  ('8d83c77b-c970-54e6-84b1-5915fdb531bb'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre habitants d’Athènes","competence":"analyser-texte","situation":"Dans les rues d’Athènes, tout le monde ne vit pas de la même façon. Quatre habitants se présentent : lis leur histoire et retrouve leur place dans la cité.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Quatre présentations","auteur":"Texte écrit pour l’exercice","blocs":["Ménon a vingt ans. Son père et sa mère sont athéniens. Il vote à l’Ecclésia, l’assemblée du peuple.","Hippias est marchand. Il est né à Corinthe et vit libre à Athènes depuis dix ans. Il paie un impôt et sert à l’armée, mais il ne sera jamais citoyen.","Sosias travaille dans les mines d’argent du Laurion. Il appartient à un maître : pour la loi, c’est un bien.","Thaïs est née à Athènes de parents athéniens. Elle est libre, mais elle ne vote pas : un tuteur décide pour elle."]}],"questions":[{"enonce":"Touche le nom de **l’assemblée** où les citoyens votent.","aide":"Cherche où Ménon exerce son droit de vote.","type":"zone","document":"recit","multiple":false},{"enonce":"Touche le mot qui dit **comment la loi voit un esclave**.","aide":"Lis ce que le récit dit de Sosias : à qui appartient-il ?","type":"zone","document":"recit","multiple":false},{"enonce":"Classe chaque personne dans son groupe.","aide":"Les métèques sont des étrangers libres ; les esclaves appartiennent à un maître.","type":"categories","categories":[{"id":"c0","texte":"Citoyen"},{"id":"c1","texte":"Métèque"},{"id":"c2","texte":"Esclave"},{"id":"c3","texte":"Femme"}],"items":[{"id":"i0","texte":"Hippias"},{"id":"i1","texte":"Un prisonnier de guerre vendu"},{"id":"i2","texte":"Lydos, un étranger libre installé à Athènes"},{"id":"i3","texte":"Ménon"},{"id":"i4","texte":"Sosias"},{"id":"i5","texte":"Thaïs"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"Les citoyens athéniens votent à l’**Ecclésia**, l’assemblée du peuple."},{"cle":{"type":"zone","ids":["m71"]},"explication":"Pour la loi, un esclave est un **bien** : on peut l’acheter, le vendre, le posséder."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c1","i3":"c0","i4":"c2","i5":"c3"}},"explication":"Ménon est **citoyen**, Hippias est un **métèque** (étranger libre), Sosias est un **esclave**, Thaïs est une **femme** libre sans droits politiques."}]$ex$::jsonb),
  ('8d83c77b-c970-54e6-84b1-5915fdb531bb'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui vote à Athènes ?","competence":"lire-graphique","situation":"En 451 av. J.-C., Périclès fait voter une nouvelle règle pour devenir citoyen. Compare cette règle aux habitants de la cité sur un diagramme imaginé.","documents":[{"id":"habitants","type":"graphique","forme":"secteurs","titre":"Les habitants d’une cité comme Athènes","source":"Proportions imaginées, d’après le cours (un habitant sur sept est citoyen).","categories":["Citoyens (hommes adultes)","Métèques","Esclaves","Femmes et enfants libres"],"series":[{"nom":"Part des habitants","valeurs":[14,10,50,26]}]},{"id":"regle","type":"texte","genre":"source","titre":"La règle de 451 av. J.-C.","auteur":"Texte écrit pour l’exercice","blocs":["En 451 av. J.-C., sur proposition de Périclès, la cité décide que, pour être citoyen, il faut être un homme libre, né d’un père citoyen et d’une mère fille de citoyen.","Trois jeunes de dix-huit ans se présentent à leur dème : Aristos, dont le père est citoyen et la mère fille de citoyen ; Dion, dont le père est citoyen mais dont la mère est une étrangère ; Pyrrhos, né esclave."]}],"questions":[{"enonce":"Touche la part des habitants qui **peuvent voter**.","aide":"Seuls les citoyens votent : cherche la part des hommes adultes citoyens.","type":"zone","document":"habitants","multiple":false},{"enonce":"Quel pourcentage des habitants **ne peut pas voter** ?","aide":"Retire la part des citoyens à 100.","type":"nombre","unite":"%"},{"enonce":"Selon la règle de 451, quels jeunes **ne seront pas** inscrits comme citoyens ?","aide":"Vérifie les trois conditions : homme libre, père citoyen, mère fille de citoyen.","type":"choix","options":[{"id":"a","texte":"Aristos et Dion"},{"id":"b","texte":"Dion et Pyrrhos"},{"id":"c","texte":"Aristos seulement"},{"id":"d","texte":"Aristos et Pyrrhos"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Compare avec la nôtre : nous élisons des représentants, et tous les adultes peuvent voter.","type":"trous","segments":["La démocratie athénienne est ",0," (on vote soi-même les lois) mais aussi ",1," à une minorité."],"banque":["représentative","universelle","restreinte","directe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Seuls les **citoyens** votent. Ils forment une petite part des habitants."},{"cle":{"type":"nombre","valeur":86,"tolerance":0},"affichage":"86 %","explication":"100 − 14 = **86 %** des habitants ne votent pas."},{"cle":{"type":"choix","ids":["b"]},"explication":"Aristos remplit les conditions. **Dion** (mère étrangère) et **Pyrrhos** (né esclave) sont refusés."},{"cle":{"type":"trous","trous":[["directe"],["restreinte"]]},"affichage":"directe · restreinte","explication":"À Athènes, la démocratie est **directe** (on vote soi-même) mais **restreinte** : un habitant sur sept seulement vote."}]$ex$::jsonb),
  ('8d83c77b-c970-54e6-84b1-5915fdb531bb'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Devenir citoyen d’Athènes","competence":"analyser-document","situation":"Pour devenir citoyen, un jeune Athénien suit un parcours précis. Une fois citoyen, il reçoit des droits, mais il a aussi des devoirs. Étudie ce parcours et classe ce que fait un citoyen.","documents":[{"id":"parcours","type":"chaine","disposition":"colonne","titre":"Le parcours d’un jeune Athénien","noeuds":[{"id":"z1","texte":"Inscrit dans son dème à 18 ans"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Serment de défendre la cité"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"}]},{"id":"actes","type":"tableau","titre":"Huit choses qu’un citoyen athénien fait ou reçoit","source":"D’après le cours.","colonnes":["N°","Un citoyen athénien…"],"lignes":[[1,"vote à l’Ecclésia"],[2,"sert dans l’armée"],[3,"peut être tiré au sort"],[4,"paie l’impôt, s’il est riche"],[5,"possède de la terre"],[6,"finance une trière (liturgie)"],[7,"est jugé par ses pairs"],[8,"participe aux cultes de la cité"]]}],"questions":[{"enonce":"Que met-on dans la case « ? » du parcours ?","aide":"Entre l’inscription et le serment de défendre la cité, que fait le jeune homme ?","type":"choix","options":[{"id":"a","texte":"Un voyage de deux ans à l’étranger"},{"id":"b","texte":"Un mariage arrangé par la famille"},{"id":"c","texte":"Une année d’études auprès d’un philosophe"},{"id":"d","texte":"L’éphébie : deux ans de service militaire"}],"multiple":false},{"enonce":"À quel âge, au plus tôt, un jeune Athénien termine-t-il l’éphébie ?","aide":"Il commence à 18 ans et l’éphébie dure deux ans.","type":"nombre","unite":"ans"},{"enonce":"Classe chaque ligne du tableau : droit ou devoir ?","aide":"Un droit est ce que la cité te donne ; un devoir est ce que tu lui dois.","type":"categories","categories":[{"id":"c0","texte":"Droit"},{"id":"c1","texte":"Devoir"}],"items":[{"id":"i0","texte":"Financer une trière"},{"id":"i1","texte":"Voter à l’Ecclésia"},{"id":"i2","texte":"Payer l’impôt"},{"id":"i3","texte":"Être jugé par ses pairs"},{"id":"i4","texte":"Posséder de la terre"},{"id":"i5","texte":"Être tiré au sort"},{"id":"i6","texte":"Servir dans l’armée"},{"id":"i7","texte":"Participer aux cultes"}]},{"enonce":"Que veut dire « être citoyen, c’est appartenir et devoir » ?","aide":"Regarde la colonne des devoirs : que doit-on à la cité ?","type":"choix","options":[{"id":"a","texte":"Avoir seulement des droits, sans aucun devoir pour la cité"},{"id":"b","texte":"Avoir des droits, mais aussi des devoirs envers la cité"},{"id":"c","texte":"Être le propriétaire de tous les esclaves de la cité"},{"id":"d","texte":"Ne rien devoir à personne dans toute la cité"}],"multiple":false}]}$ex$::jsonb,
