   $ex${"titre":"La louve et les jumeaux","competence":"analyser-texte","situation":"Les Romains racontaient comment leur ville était née. Lis cette légende, puis place la date de la fondation sur la frise.","documents":[{"id":"legende","type":"texte","genre":"recit","titre":"La fondation de Rome","auteur":"Légende adaptée d’après Tite-Live, texte écrit pour l’exercice","blocs":["Selon la légende, deux frères jumeaux, Romulus et Rémus, sont fils du dieu Mars. Abandonnés sur le Tibre, ils sont recueillis et allaités par une louve.","Devenus adultes, ils décident de fonder une ville. Mais ils se disputent, et Romulus tue son frère. La ville prend le nom de Romulus : c’est Rome."]},{"id":"frise","type":"frise","titre":"Rome selon la tradition","debut":-800,"fin":-500,"pas":100,"source":"Dates traditionnelles.","evenements":[{"id":"z1","date":-753,"nom":"Fondation légendaire"},{"id":"z2","date":-509,"nom":"République"}]}],"questions":[{"enonce":"Touche l’animal qui **allaite** les jumeaux.","aide":"Les jumeaux sont abandonnés au bord du Tibre : qui les recueille ?","type":"zone","document":"legende","multiple":false},{"enonce":"Que devient Rémus dans la légende ?","aide":"Relis le deuxième paragraphe.","type":"choix","options":[{"id":"a","texte":"Il part fonder une autre ville"},{"id":"b","texte":"Il est allaité par Mars"},{"id":"c","texte":"Romulus le tue après une dispute"},{"id":"d","texte":"Il devient le premier roi de Rome"}],"multiple":false},{"enonce":"Touche sur la frise **la date légendaire de la fondation** de Rome.","aide":"Cherche le nom qui parle de fondation et de légende.","type":"zone","document":"frise","multiple":false}]}$ex$::jsonb,
