  ('485427dc-e28f-5cfc-a3c1-855d7966a203'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un vote qui ne compte pas pareil","competence":"analyser-document","situation":"À Rome, tous les citoyens ne pèsent pas pareil dans un vote. Lis la règle d’un vote imaginé, puis regarde comment on élit les consuls.","documents":[{"id":"vote","type":"tableau","titre":"Un vote par groupes (exemple imaginé)","source":"Chiffres imaginés pour l’exercice, d’après le vote par groupes pondérés.","colonnes":["Groupe","Citoyens","Voix"],"lignes":[["Les plus riches",600,60],["Tous les autres",9400,40]],"enteteLignes":true},{"id":"texte","type":"texte","genre":"article","titre":"L’élection des consuls","auteur":"Texte écrit pour l’exercice","blocs":["Chaque année, les comices élisent deux consuls, chefs de l’État et de l’armée. Leur mandat dure un an, pas un jour de plus.","Ensuite, ils entrent au Sénat, qui compte environ 300 anciens magistrats nommés à vie."]}],"questions":[{"enonce":"Touche la **durée** du mandat d’un consul.","aide":"Cherche le mot qui dit combien de temps ils restent en fonction.","type":"zone","document":"texte","multiple":true},{"enonce":"Dans le groupe « Tous les autres », combien de citoyens se partagent **une** voix ?","aide":"Divise le nombre de citoyens du groupe par son nombre de voix.","type":"nombre","unite":"citoyens"},{"enonce":"Pourquoi dit-on que la République romaine est oligarchique ?","aide":"Regarde qui possède 60 voix sur 100 dans le tableau.","type":"choix","options":[{"id":"a","texte":"Le peuple tire au sort tous les magistrats chaque année"},{"id":"b","texte":"Le vrai pouvoir est aux mains de familles riches"},{"id":"c","texte":"Un seul homme décide de tout, comme le ferait un roi"},{"id":"d","texte":"Tous les habitants ont exactement le même poids de vote"}],"multiple":false},{"enonce":"Associe chaque institution à ce qu’elle est.","aide":"Le Sénat est formé d’anciens magistrats.","type":"association","gauche":[{"id":"g0","texte":"Les comices"},{"id":"g1","texte":"Les magistrats"},{"id":"g2","texte":"Le Sénat"}],"droite":[{"id":"d0","texte":"Les assemblées qui élisent et votent les lois"},{"id":"d1","texte":"Environ 300 anciens magistrats, nommés à vie"},{"id":"d2","texte":"Des élus pour un an, par deux au moins"}]}]}$ex$::jsonb,
