  ('485427dc-e28f-5cfc-a3c1-855d7966a203'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le tribun dit « veto ! »","competence":"analyser-document","situation":"La République romaine n’est pas égalitaire : des luttes opposent patriciens et plébéiens. Une scène imaginée montre l’arme des plébéiens ; un schéma montre comment la République se termine.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Une séance au Sénat","auteur":"Texte écrit pour l’exercice","blocs":["Le Sénat veut voter une loi qui oblige les plébéiens à payer plus d’impôts. Les patriciens applaudissent. Mais un tribun de la plèbe, Caius, se lève et crie : « Veto ! »","Ce mot veut dire « je m’oppose ». Grâce à lui, la loi est bloquée : les plébéiens ont obtenu cette arme après de longues luttes."]},{"id":"fin","type":"chaine","disposition":"colonne","titre":"La fin de la République","noeuds":[{"id":"z1","texte":"Les conquêtes enrichissent une minorité"},{"id":"z2","texte":"La crise sociale s’aggrave"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Guerre civile"},{"id":"z5","texte":"L’Empire"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche le mot que prononce le tribun pour **bloquer la loi**.","aide":"C’est un mot latin, entre guillemets, à la fin du premier paragraphe.","type":"zone","document":"scene","multiple":false},{"enonce":"Associe chaque groupe ou chaque fonction à sa description.","aide":"Les tribuns défendent les plébéiens.","type":"association","gauche":[{"id":"g0","texte":"Les patriciens"},{"id":"g1","texte":"Les plébéiens"},{"id":"g2","texte":"Les tribuns de la plèbe"},{"id":"g3","texte":"Les consuls"}],"droite":[{"id":"d0","texte":"Les grandes familles"},{"id":"d1","texte":"Chefs de l’État et de l’armée"},{"id":"d2","texte":"Ils ont le droit de veto"},{"id":"d3","texte":"Le reste des citoyens"}]},{"enonce":"Qui est citoyen romain, et qui est exclu ?","aide":"Les femmes, les esclaves et les étrangers sont exclus, comme à Athènes.","type":"categories","categories":[{"id":"c0","texte":"Citoyen romain"},{"id":"c1","texte":"Exclu de la citoyenneté"}],"items":[{"id":"i0","texte":"Un étranger"},{"id":"i1","texte":"Une femme"},{"id":"i2","texte":"Un patricien"},{"id":"i3","texte":"Un esclave"},{"id":"i4","texte":"Un plébéien"}]},{"enonce":"Quelle étape manque dans la case « ? » de la chaîne ?","aide":"Qui gagne du pouvoir quand l’armée est fidèle à son chef ?","type":"choix","options":[{"id":"a","texte":"Le Sénat est supprimé pour toujours"},{"id":"b","texte":"Les plébéiens obtiennent le droit de veto"},{"id":"c","texte":"Les généraux s’appuient sur leurs armées"},{"id":"d","texte":"Les consuls deviennent des rois élus"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"**Veto** signifie « je m’oppose » : c’est le droit des tribuns de la plèbe."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"Les **patriciens** sont les grandes familles, les **plébéiens** le reste des citoyens. Les **tribuns** ont le droit de veto, les **consuls** dirigent l’État et l’armée."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0"}},"explication":"Patriciens et plébéiens sont citoyens. Les **femmes, les esclaves et les étrangers** sont exclus : la République est très inégalitaire."},{"cle":{"type":"choix","ids":["c"]},"explication":"Quand la crise s’aggrave, des **généraux s’appuient sur leurs armées** : cela mène à la guerre civile, puis à l’Empire."}]$ex$::jsonb),
  ('0167f885-4726-5db9-8eed-8b09a19bcd39'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une bibliothèque plutôt qu’un livre","competence":"analyser-document","situation":"On parle souvent de la Bible comme d’un seul livre. En réalité, la Bible hébraïque est une vraie bibliothèque. Lis sa fiche pour comprendre ce qu’elle contient.","documents":[{"id":"fiche","type":"fiche","modele":"panneau","entete":"La Bible hébraïque","sousTitre":"Fiche de présentation","emoji":"📚","source":"Fiche écrite pour l’exercice, d’après le cours.","lignes":[{"texte":"Nature","valeur":"une collection de textes","id":"z1"},{"texte":"Contenu","valeur":"récits, lois, poèmes, prophéties","id":"z2"},{"texte":"Rédaction","valeur":"du VIIIe au IIe siècle av. J.-C.","id":"z3"},{"texte":"Nom chez les chrétiens","valeur":"Ancien Testament","id":"z4"}]}],"questions":[{"enonce":"Touche la ligne qui indique **le nom** que les chrétiens donnent à ces textes.","aide":"Cherche le mot « chrétiens » dans la fiche.","type":"zone","document":"fiche","multiple":false},{"enonce":"Combien de siècles sépare le VIIIe siècle av. J.-C. du IIe siècle av. J.-C. ?","aide":"Les deux siècles sont avant J.-C. : soustrais le plus petit numéro au plus grand.","type":"nombre","unite":"siècles"},{"enonce":"D’après la fiche, la Bible hébraïque est…","aide":"Regarde les lignes « Nature » et « Rédaction ».","type":"choix","options":[{"id":"a","texte":"le livre d’un seul et unique auteur de l’époque"},{"id":"b","texte":"le journal personnel tenu par un roi de Jérusalem"},{"id":"c","texte":"une collection de textes écrits sur des siècles"},{"id":"d","texte":"un recueil rédigé en une seule et même année"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"On les appelle aussi le Pentateuque.","type":"trous","segments":["Les cinq premiers livres de la Bible hébraïque forment la ",0,"."],"banque":["Prophétie","Genèse","Torah","Alliance"]}]}$ex$::jsonb,
