  ('0167f885-4726-5db9-8eed-8b09a19bcd39'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Abraham, Moïse et l’exil","competence":"analyser-document","situation":"La Bible hébraïque raconte l’histoire des Hébreux. Lis ce que dit le récit, puis place deux dates sûres sur une frise : celles de l’exil à Babylone.","documents":[{"id":"recit","type":"texte","genre":"source","titre":"Deux grands récits","auteur":"D’après la Bible hébraïque, texte adapté et abrégé","blocs":["Selon le récit biblique, Abraham reçoit une promesse de Dieu : une terre et une descendance nombreuse. Cette promesse s’appelle l’Alliance.","Plus tard, selon le même récit, Moïse fait sortir les Hébreux d’Égypte : c’est l’Exode. Au mont Sinaï, il reçoit les Dix Commandements."]},{"id":"frise","type":"frise","titre":"L’exil à Babylone","debut":-600,"fin":-500,"pas":25,"source":"Dates sûres : la prise de Jérusalem et la reconstruction du Temple.","periodes":[{"id":"z1","debut":-587,"fin":-515,"nom":"Exil et retour","teinte":"ambre"}],"evenements":[{"id":"z2","date":-587,"nom":"Temple détruit"},{"id":"z3","date":-515,"nom":"Temple rebâti"}]}],"questions":[{"enonce":"Touche, dans le récit, **le nom de la promesse** de Dieu à Abraham.","aide":"Cherche le mot qui commence par une majuscule, dans le premier paragraphe.","type":"zone","document":"recit","multiple":false},{"enonce":"Associe chaque personnage à ce que raconte le récit biblique.","aide":"Le Temple de Jérusalem est l’œuvre d’un roi.","type":"association","gauche":[{"id":"g0","texte":"Abraham"},{"id":"g1","texte":"Moïse"},{"id":"g2","texte":"Salomon"}],"droite":[{"id":"d0","texte":"Il bâtit le Temple de Jérusalem"},{"id":"d1","texte":"Il reçoit la promesse de l’Alliance"},{"id":"d2","texte":"Il fait sortir les Hébreux d’Égypte"}]},{"enonce":"Touche sur la frise la période qui va **de la destruction du Temple à sa reconstruction**.","aide":"Cherche la bande qui relie les deux événements.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la destruction du Temple (−587) de sa reconstruction (−515) ?","aide":"Les deux dates sont avant J.-C. : soustrais la plus petite à la plus grande.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
