un","motif":"clair"},{"forme":"rect","x":260,"y":34,"l":40,"h":28,"teinte":"brun","motif":"clair"},{"forme":"rect","x":38,"y":34,"l":30,"h":28,"teinte":"brun","motif":"clair"},{"forme":"rect","x":74,"y":34,"l":30,"h":28,"teinte":"brun","motif":"clair"},{"forme":"rect","x":280,"y":156,"l":30,"h":40,"teinte":"brun","motif":"clair"},{"forme":"rect","x":188,"y":206,"l":40,"h":28,"teinte":"brun","motif":"clair"},{"forme":"rect","x":236,"y":206,"l":32,"h":28,"teinte":"brun","motif":"clair"},{"forme":"ligne","de":[335,85],"a":[292,85],"teinte":"bleu","fleche":"fin","style":"pointilles","id":"z13","zone":true},{"forme":"texte","x":322,"y":76,"texte":"Eau","taille":"petit","ancre":"milieu"},{"forme":"texte","x":36,"y":14,"texte":"N ↑","taille":"petit","gras":true}]}],"questions":[{"enonce":"Julia veut voir la **grande place** où l’on discute, où l’on fait des affaires et où l’on rend la justice. Touche-la.","aide":"C’est la place publique, juste à côté de l’endroit où les deux grandes rues se croisent.","type":"zone","document":"plan","multiple":false},{"enonce":"Touche la grande rue qui va du **nord au sud** : le **cardo**.","aide":"Regarde la flèche N en haut du plan. Le cardo est vertical.","type":"zone","document":"plan","multiple":false},{"enonce":"Touche les **deux** lieux où l’on va voir des spectacles.","aide":"L’un a la forme d’un demi-cercle, l’autre d’un ovale, et il est hors des murs.","type":"zone","document":"plan","multiple":true},{"enonce":"Compte les **portes** dans le rempart de la ville (les ronds bruns).","aide":"Il y en a une au bout de chaque grande rue.","type":"nombre","unite":"portes"},{"enonce":"Les rues se croisent à angle droit, comme les cases d’une grille. On appelle ce plan un plan en…","aide":"Pense à un jeu de dames.","type":"choix","options":[{"id":"a","texte":"damier"},{"id":"b","texte":"spirale"},{"id":"c","texte":"étoile"},{"id":"d","texte":"cercle"}],"multiple":false}]}$ex$::jsonb,
