   $ex${"titre":"Tertius devient citoyen romain","competence":"analyser-texte","situation":"Trois générations d’une même famille de Lugdunum vivent-elles de la même façon ? En lisant la lettre de Tertius et un tableau, tu vas comprendre comment la romanisation a changé leur vie… et pourquoi elle n’a pas touché tout le monde.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"La lettre de Tertius","auteur":"Texte écrit pour l’exercice","blocs":["Lugdunum, l’an 213. Mon grand-père ne parlait que le gaulois. Mon père a appris le latin pour vendre son vin sur le forum.","Moi, je vais aux thermes avec mes amis et au théâtre le dimanche. Et depuis l’édit de l’empereur Caracalla, l’an dernier, nous sommes tous citoyens romains.","Mon cousin, lui, vit dans un village de campagne. Il parle toujours gaulois et ne va jamais en ville."]},{"id":"compar","type":"tableau","titre":"Ville de Gaule ou village de campagne ?","source":"Tableau écrit pour l’exercice, d’après le cours.","colonnes":["","Dans la ville","Dans la campagne"],"lignes":[["Langue","Latin et gaulois","Surtout gaulois"],["Équipements","Forum, thermes, théâtre","Fermes et petits sanctuaires"],["Dieux","Dieux gaulois et dieux romains associés","Dieux gaulois"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les **trois mots** qui montrent que la famille de Tertius a adopté le mode de vie romain.","aide":"Cherche une langue, un lieu pour les affaires et un lieu pour se baigner.","type":"zone","document":"lettre","multiple":true,"portee":[0,1]},{"enonce":"Range ces moments de l’histoire de la famille, du plus **ancien** au plus **récent**.","aide":"La lettre raconte les générations : grand-père, père, puis Tertius.","type":"ordre","items":[{"id":"a","texte":"L’empereur Caracalla rend tous les hommes libres citoyens"},{"id":"b","texte":"Le grand-père ne parle que le gaulois"},{"id":"c","texte":"Le père apprend le latin pour vendre son vin"},{"id":"d","texte":"Tertius écrit sa lettre à Lugdunum"}]},{"enonce":"D’après le tableau, pourquoi le cousin de Tertius parle-t-il toujours gaulois ?","aide":"Compare la colonne « Dans la campagne » à la colonne « Dans la ville ».","type":"choix","options":[{"id":"a","texte":"Les paysans refusent de payer des impôts"},{"id":"b","texte":"Rome interdit le latin dans les campagnes"},{"id":"c","texte":"La romanisation touche surtout les villes"},{"id":"d","texte":"Il n’existe aucun village en Gaule"}],"multiple":false},{"enonce":"Complète la phrase sur l’édit de 212.","aide":"Tertius en parle dans le deuxième paragraphe de sa lettre.","type":"trous","segments":["L’édit de ",0," donne la citoyenneté romaine à tous les ",1," de l’Empire."],"banque":["Caracalla","esclaves","soldats","hommes libres","Constantin"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m23","m28"]},"explication":"**Latin**, **forum** et **thermes** : la langue, la place publique et les bains romains."},{"cle":{"type":"ordre","ids":["b","c","a","d"]},"explication":"On suit **trois générations** : le grand-père gaulois, le père qui apprend le latin, puis l’édit de Caracalla en 212, et enfin Tertius qui écrit en 213."},{"cle":{"type":"choix","ids":["c"]},"explication":"La romanisation touche **surtout les villes et les élites** : les campagnes gardent longtemps leurs langues et leurs coutumes."},{"cle":{"type":"trous","trous":[["caracalla"],["hommes libres"]]},"affichage":"Caracalla · hommes libres","explication":"L’édit de **Caracalla** (212) donne la citoyenneté à tous les **hommes libres** : un vaincu devient un citoyen."}]$ex$::jsonb),
