   $ex${"titre":"Thaïs et le voyageur d’Éphèse","competence":"analyser-document","situation":"À Corinthe, vers l’an 60, une tisserande entend parler de Jésus par un voyageur. En croisant son récit et la carte, tu vas comprendre pourquoi cette religion se diffuse si vite.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Le récit de Thaïs","auteur":"Texte écrit pour l’exercice","blocs":["Corinthe, vers l’an 60. Thaïs, tisserande, raconte : « Je ne suis pas juive. Un voyageur venu d’Éphèse par bateau nous a parlé d’un homme, Jésus, que ses disciples disent ressuscité.","Il parle grec, comme nous tous ici : nous l’avons compris sans peine. Chaque semaine, nous nous réunissons dans la maison de Marcus. Nous lisons des textes de la Bible, que les juifs nous ont transmis, et nous partageons un repas.","Hier, trois nouveaux membres ont été baptisés. »"]},{"id":"carte3","type":"carte","titre":"La mer Égée entre Éphèse et Corinthe","fond":"mediterranee","cadrage":[18,34,32,42],"lieux":[{"id":"z1","lieu":"ephese","symbole":"point","nom":"Éphèse","teinte":"violet"},{"id":"z2","lieu":"corinthe","symbole":"point","nom":"Corinthe","teinte":"violet"}],"traits":[{"points":["ephese","corinthe"],"style":"fleche","teinte":"corail"}]}],"questions":[{"enonce":"Touche le **mot** qui explique pourquoi Thaïs comprend le voyageur.","aide":"C’est une langue.","type":"zone","document":"recit","multiple":false,"portee":[1]},{"enonce":"Touche la ville **d’où vient** le voyageur.","aide":"Relis le début du récit : le voyageur vient « d’Éphèse ».","type":"zone","document":"carte3","multiple":false},{"enonce":"Associe chaque facteur à son effet.","aide":"Un facteur = une cause. Cherche ce qu’elle permet.","type":"association","gauche":[{"id":"g0","texte":"Les routes et la paix de l’Empire"},{"id":"g1","texte":"Le grec, langue commune"},{"id":"g2","texte":"L’ouverture aux non-juifs"}],"droite":[{"id":"d0","texte":"On se comprend"},{"id":"d1","texte":"La religion devient universelle"},{"id":"d2","texte":"On circule facilement"}]},{"enonce":"Range ce que décrit Thaïs.","aide":"Le baptême remplace la circoncision ; la Bible vient du judaïsme.","type":"categories","categories":[{"id":"c0","texte":"Hérité du judaïsme"},{"id":"c1","texte":"Propre au christianisme"}],"items":[{"id":"i0","texte":"Croire que Jésus est ressuscité"},{"id":"i1","texte":"Croire en un seul Dieu"},{"id":"i2","texte":"Être baptisé"},{"id":"i3","texte":"Lire des textes de la Bible"}]},{"enonce":"Thaïs n’est pas juive. Pourquoi peut-elle pourtant rejoindre la communauté ?","aide":"Pense à ce qui change le christianisme d’un mouvement juif en religion universelle.","type":"choix","options":[{"id":"a","texte":"Le christianisme s’ouvre aussi aux non-juifs"},{"id":"b","texte":"Elle a reçu un ordre de l’empereur"},{"id":"c","texte":"Tout le monde devient chrétien à Corinthe"},{"id":"d","texte":"Elle a payé pour y entrer"}],"multiple":false}]}$ex$::jsonb,
