  ('319cde17-8032-5331-9e3e-728d758e3a99'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un magistrat inquiet","competence":"analyser-texte","situation":"Dans une ville de l’Empire, au IIIe siècle, un magistrat doit faire respecter l’ordre. Voici ce qu’il raconte sur des chrétiens. Pourquoi son rapport est-il si embarrassé ?","documents":[{"id":"rapport","type":"texte","genre":"source","titre":"Le rapport d’un magistrat","auteur":"Texte imaginé, écrit pour l’exercice","blocs":["Je suis magistrat dans une ville de province. Aujourd’hui, j’ai fait venir quelques personnes qui se disent chrétiennes.","Je leur ai demandé de verser un peu d’encens devant la statue de l’empereur, comme tous les habitants. Elles ont refusé. Je les ai interrogées : elles ne sont pas des voleurs, mais leur refus m’inquiète."]}],"questions":[{"enonce":"Touche l’**objet** devant lequel le magistrat demande un geste de respect.","aide":"Il représente l’empereur.","type":"zone","document":"rapport","multiple":false,"portee":[1]},{"enonce":"Rome tolère presque tous les cultes. À quelle condition ?","aide":"Regarde ce que le magistrat demande aux chrétiens.","type":"choix","options":[{"id":"a","texte":"Avoir au moins mille fidèles"},{"id":"b","texte":"Payer un impôt spécial"},{"id":"c","texte":"Honorer aussi l’empereur"},{"id":"d","texte":"Ne pas construire de temples"}],"multiple":false},{"enonce":"Complète l’explication.","aide":"Refuser de saluer l’empereur, c’est refuser de lui être fidèle.","type":"trous","segments":["Pour Rome, le refus des chrétiens est un acte de ",0," politique, et pas seulement une opinion religieuse."],"banque":["fête","curiosité","déloyauté","loyauté"]}]}$ex$::jsonb,
