  ('319cde17-8032-5331-9e3e-728d758e3a99'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Des traces et des dates","competence":"se-reperer-temps","situation":"Les chrétiens ont laissé des traces sous la ville de Rome et des textes sur l’édit qui a changé leur sort. Une frise et un panneau de musée t’aident à les situer.","documents":[{"id":"frise","type":"frise","titre":"Des persécutions à la religion officielle","debut":50,"fin":400,"pas":25,"periodes":[{"id":"z1","debut":303,"fin":311,"nom":"Persécution de Dioclétien","teinte":"corail"}],"evenements":[{"id":"z2","date":64,"nom":"Néron accuse les chrétiens"},{"id":"z3","date":313,"nom":"Édit de Milan"},{"id":"z4","date":325,"nom":"Concile de Nicée"},{"id":"z5","date":380,"nom":"Édit de Thessalonique"}]},{"id":"cata","type":"fiche","modele":"panneau","entete":"Les catacombes de Rome","sousTitre":"Panneau de visite","emoji":"🕯️","lignes":[{"texte":"Des galeries creusées sous la ville","id":"z6"},{"texte":"Les chrétiens y enterrent leurs morts","id":"z7"},{"texte":"Peintures et inscriptions sur les murs","id":"z8"},{"texte":"Un signe discret : le poisson (en grec, ichthus)","id":"z9"}]}],"questions":[{"enonce":"Combien d’années séparent l’édit de Milan (313) de l’édit de Thessalonique (380) ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Combien d’années dure la persécution de Dioclétien, d’après la frise ?","aide":"Regarde le début et la fin de la bande.","type":"nombre","unite":"ans"},{"enonce":"Quel événement a lieu entre l’édit de Milan et l’édit de Thessalonique ?","aide":"Cherche sur la frise ce qui se trouve entre 313 et 380.","type":"choix","options":[{"id":"a","texte":"La mort de Jésus"},{"id":"b","texte":"L’incendie de Rome sous Néron"},{"id":"c","texte":"Le concile de Nicée"},{"id":"d","texte":"La persécution de Dioclétien"}],"multiple":false},{"enonce":"Touche la ligne du panneau qui parle d’un **signe** que les chrétiens utilisaient pour se reconnaître.","aide":"Un animal aquatique.","type":"zone","document":"cata","multiple":false},{"enonce":"Pourquoi ce signe est-il « discret » ?","aide":"Pense à la période où l’on pouvait être arrêté pour sa foi.","type":"choix","options":[{"id":"a","texte":"Parce qu’il est trop petit pour être dessiné"},{"id":"b","texte":"Parce que les Romains le connaissaient tous"},{"id":"c","texte":"Parce que les chrétiens étaient parfois persécutés"},{"id":"d","texte":"Parce que l’empereur l’avait choisi"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":67,"tolerance":0},"affichage":"67 ans","explication":"380 − 313 = **67 ans**. En moins d’un siècle, les persécutés deviennent la religion officielle."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 ans","explication":"De 303 à 311 : 311 − 303 = **8 ans**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **concile de Nicée** a lieu en 325, entre les deux édits."},{"cle":{"type":"zone","ids":["z9"]},"explication":"Le **poisson** (en grec *ichthus*) est un signe discret de reconnaissance."},{"cle":{"type":"choix","ids":["c"]},"explication":"Pendant les persécutions, mieux valait ne pas se faire repérer : un **signe discret** permettait de se reconnaître."}]$ex$::jsonb),
