   $ex${"titre":"Le Ciel est-il mécontent ?","competence":"analyser-document","situation":"Chaque dynastie chinoise tient son pouvoir du Ciel… tant qu’il le veut bien. Lis le récit de Wei et regarde le schéma du pouvoir pour comprendre ce que pensent les Chinois de leur empereur.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Une année difficile","auteur":"Texte écrit pour l’exercice","blocs":["Chang’an, sous les Han. Cette année, une grande sécheresse a ruiné les récoltes. Dans plusieurs villages, des paysans se révoltent.","Wei, jeune lettré, a réussi le concours. Il travaille pour l’empereur. Il entend les vieux fonctionnaires murmurer : « Le Ciel est mécontent. »"]},{"id":"pouvoir","type":"schema","titre":"Qui gouverne en Chine sous les Han ?","largeur":320,"hauteur":300,"source":"Schéma simplifié écrit pour l’exercice.","elements":[{"forme":"rect","x":80,"y":20,"l":160,"h":40,"arrondi":8,"teinte":"bleu","motif":"clair","id":"z1","zone":true,"texte":"Le Ciel"},{"forme":"rect","x":80,"y":100,"l":160,"h":44,"arrondi":8,"teinte":"jaune","motif":"clair","id":"z2","zone":true,"texte":"L’empereur"},{"forme":"rect","x":80,"y":184,"l":160,"h":44,"arrondi":8,"teinte":"violet","motif":"clair","id":"z3","zone":true,"texte":"Fonctionnaires lettrés"},{"forme":"rect","x":80,"y":260,"l":160,"h":34,"arrondi":8,"teinte":"vert","motif":"clair","id":"z4","zone":true,"texte":"Le peuple"},{"forme":"ligne","de":[160,60],"a":[160,100],"fleche":"fin"},{"forme":"ligne","de":[160,144],"a":[160,184],"fleche":"fin"},{"forme":"ligne","de":[160,228],"a":[160,260],"fleche":"fin"},{"forme":"texte","x":170,"y":84,"texte":"Mandat","taille":"petit"},{"forme":"texte","x":170,"y":168,"texte":"Ordres","taille":"petit"},{"forme":"texte","x":170,"y":249,"texte":"Impôts","taille":"petit"},{"forme":"etiquette","x":275,"y":118,"texte":"Fils du Ciel","vers":[240,122]}]}],"questions":[{"enonce":"Touche le **mot** qui désigne le phénomène naturel qui ruine les récoltes.","aide":"C’est un manque de pluie.","type":"zone","document":"recit","multiple":false,"portee":[0]},{"enonce":"Touche celui qui reçoit du Ciel le **mandat céleste**, le droit de gouverner.","aide":"Regarde vers quoi pointe la flèche « Mandat ».","type":"zone","document":"pouvoir","multiple":false},{"enonce":"Sécheresse et révoltes : que peuvent penser les Chinois ?","aide":"Souviens-toi : le mandat céleste peut se perdre.","type":"choix","options":[{"id":"a","texte":"Le Ciel retire peut-être son mandat"},{"id":"b","texte":"Le papier a été mal fabriqué"},{"id":"c","texte":"Les dieux grecs sont en colère"},{"id":"d","texte":"L’empereur doit devenir citoyen"}],"multiple":false},{"enonce":"Associe chaque notion à ce qu’elle désigne.","aide":"Reprends ce que Wei, le lettré, a passé pour travailler pour l’empereur.","type":"association","gauche":[{"id":"g0","texte":"Le concours"},{"id":"g1","texte":"Le mandat céleste"},{"id":"g2","texte":"Confucius"},{"id":"g3","texte":"Le Fils du Ciel"}],"droite":[{"id":"d0","texte":"Le droit de gouverner donné par le Ciel"},{"id":"d1","texte":"La morale de l’ordre et du respect des aînés"},{"id":"d2","texte":"Le recrutement des fonctionnaires"},{"id":"d3","texte":"L’empereur"}]}]}$ex$::jsonb,
