   $ex${"titre":"Lagos : une ville qui ne cesse de grandir","competence":"lire-graphique","situation":"En 1950, Lagos, au Nigeria, était une ville moyenne. Aujourd’hui, c’est l’une des plus grandes villes d’Afrique. Observe sa croissance.","documents":[{"id":"lagos","type":"graphique","forme":"barres","titre":"Les habitants de Lagos (Nigeria)","source":"ONU, ordres de grandeur arrondis.","categories":["1950","1970","1990","2010","Aujourd’hui"],"series":[{"nom":"Habitants","valeurs":[0.3,1.4,4.8,10.5,15],"teinte":"turquoise"}],"axeY":{"titre":"Habitants","unite":"en millions","min":0,"max":16,"pas":2},"axeX":{"titre":"Année"}}],"questions":[{"enonce":"Touche la barre qui montre **le plus d’habitants**.","aide":"C’est la barre la plus haute.","type":"zone","document":"lagos","multiple":false},{"enonce":"Combien d’habitants Lagos compte-t-elle en 2010 ? Lis le graphique, au million près.","aide":"La barre 2010 se termine un peu au-dessus de 10 sur l’axe.","type":"nombre","unite":"millions"},{"enonce":"Lagos compte 0,3 million d’habitants en 1950 et 15 millions aujourd’hui. Par combien sa population a-t-elle été multipliée ?","aide":"Divise 15 par 0,3. Pense à 150 ÷ 3.","type":"nombre"},{"enonce":"Dans une métropole qui grandit aussi vite, que se passe-t-il souvent pour les équipements ?","aide":"Pense au mot « décalage » du cours.","type":"choix","options":[{"id":"a","texte":"Ils sont construits avant l’arrivée des habitants"},{"id":"b","texte":"Ils sont toujours plus nombreux que nécessaire"},{"id":"c","texte":"Ils ne suivent pas : manque de logements, d’écoles, d’égouts"},{"id":"d","texte":"On les supprime pour faire de la place"}],"multiple":false}]}$ex$::jsonb,
